-- ── All Saints Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(' telle que l''atlas en a désormais beaucoup' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, ' telle que l''atlas en a désormais beaucoup', ''), `history`),
  `history_en` = IF(LOCATE(CAST(' such as this atlas now has many of' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, ' such as this atlas now has many of', ''), `history_en`),
  `history_es` = IF(LOCATE(CAST(' como este atlas ya tiene muchas' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ' como este atlas ya tiene muchas', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST(', wie dieser Atlas inzwischen viele hat' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, ', wie dieser Atlas inzwischen viele hat', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集如今已收录许多的' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集如今已收录许多的', '一家'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST(' كما صار لهذا الأطلس كثير منها' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, ' كما صار لهذا الأطلس كثير منها', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'All Saints Cigars';

-- ── Aruhiba ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('l''atlas ne connaît pas d''autre cigare fait de bout en bout sur une île aussi petite, et ne sait pas si la cape est d''ailleurs' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'l''atlas ne connaît pas d''autre cigare fait de bout en bout sur une île aussi petite, et ne sait pas si la cape est d''ailleurs', 'on ne sait pas si la cape est d''ailleurs'), `history`),
  `history_en` = IF(LOCATE(CAST('this atlas knows no other cigar made end to end on so small an island, and does not know whether the wrapper is from elsewhere' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'this atlas knows no other cigar made end to end on so small an island, and does not know whether the wrapper is from elsewhere', 'it is not known whether the wrapper is from elsewhere'), `history_en`),
  `history_es` = IF(LOCATE(CAST('este atlas no conoce otro puro hecho de principio a fin en una isla tan pequeña, y no sabe si la capa es de otra parte' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'este atlas no conoce otro puro hecho de principio a fin en una isla tan pequeña, y no sabe si la capa es de otra parte', 'no se sabe si la capa es de otra parte'), `history_es`),
  `history_de` = IF(LOCATE(CAST('dieser Atlas kennt keine andere Zigarre, die von Anfang bis Ende auf einer so kleinen Insel entsteht, und weiß nicht, ob das Deckblatt von anderswo kommt' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'dieser Atlas kennt keine andere Zigarre, die von Anfang bis Ende auf einer so kleinen Insel entsteht, und weiß nicht, ob das Deckblatt von anderswo kommt', 'man weiß nicht, ob das Deckblatt von anderswo kommt'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集不知道还有哪支雪茄在这么小的岛上从头到尾完成，也不知道茄衣是否来自别处' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集不知道还有哪支雪茄在这么小的岛上从头到尾完成，也不知道茄衣是否来自别处', '不知道茄衣是否来自别处'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('لا يعرف هذا الأطلس سيجارًا آخر يُصنع من أوّله إلى آخره في جزيرة بهذا الصغر، ولا يعرف إن كان الغلاف من مكان آخر' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'لا يعرف هذا الأطلس سيجارًا آخر يُصنع من أوّله إلى آخره في جزيرة بهذا الصغر، ولا يعرف إن كان الغلاف من مكان آخر', 'لا يُعرف إن كان الغلاف من مكان آخر'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Aruhiba';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(', et l''atlas ne le cite pas' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, ', et l''atlas ne le cite pas', ''), `history`),
  `history_en` = IF(LOCATE(CAST(', and the atlas does not cite it' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, ', and the atlas does not cite it', ''), `history_en`),
  `history_es` = IF(LOCATE(CAST(', y el atlas no lo cita' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ', y el atlas no lo cita', ''), `history_es`),
