-- ── Black Label Trading Co. ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","story":"« Les derniers sacrements » — la gamme fondatrice, et celle qui a donné son ton à toute l''iconographie de la maison. Corsée, roulée à l''Oveja Negra.","vitolas":["Robusto","Toro","Petit Lancero"],"wrapper":"Assemblage Oveja Negra"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","story":"Le pendant du Last Rites, dans le même registre liturgique. Feuilles du Nicaragua, du Honduras, de San Andrés et d''Équateur.","vitolas":["Robusto","Toro"],"wrapper":"Assemblage Oveja Negra"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","story":"La sainte Mort du culte populaire mexicain, dessinée par James Brown lui-même. La maison va au bout de son imagerie plutôt que de la suggérer.","vitolas":["Robusto","Toro"],"wrapper":"Assemblage Oveja Negra"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","story":"Le second nom de James Brown, novembre 2015, même fabrique — Oveja Negra — pour les assemblages moins orthodoxes. NBK, Killer Bee et Rorschach ont ouvert.","vitolas":[],"wrapper":"Habano d''Équateur"}]',
  `gamme_en` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","story":"\\"The last rites\\" — the founding range, and the one that set the tone for the whole of the house''s iconography. Full-bodied, rolled at Oveja Negra.","vitolas":["Robusto","Toro","Petit Lancero"],"wrapper":"Oveja Negra blend"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","story":"The counterpart to Last Rites, in the same liturgical register. Leaves from Nicaragua, Honduras, San Andrés and Ecuador.","vitolas":["Robusto","Toro"],"wrapper":"Oveja Negra blend"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","story":"The Holy Death of Mexican popular devotion, drawn by James Brown himself. The house carries its imagery through rather than merely hinting at it.","vitolas":["Robusto","Toro"],"wrapper":"Oveja Negra blend"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","story":"James Brown''s second name, November 2015, same factory — Oveja Negra — for the less orthodox blends. NBK, Killer Bee and Rorschach opened.","vitolas":[],"wrapper":"Ecuadorian Habano"}]',
  `gamme_es` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","story":"«Los últimos sacramentos»: la gama fundadora, y la que dio el tono a toda la iconografía de la casa. Fuerte, liada en la Oveja Negra.","vitolas":["Robusto","Toro","Petit Lancero"],"wrapper":"Ligada Oveja Negra"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","story":"El contrapunto del Last Rites, en el mismo registro litúrgico. Hojas de Nicaragua, Honduras, San Andrés y Ecuador.","vitolas":["Robusto","Toro"],"wrapper":"Ligada Oveja Negra"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","story":"La Santa Muerte de la devoción popular mexicana, dibujada por el propio James Brown. La casa lleva su imaginería hasta el final en vez de solo sugerirla.","vitolas":["Robusto","Toro"],"wrapper":"Ligada Oveja Negra"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","story":"El segundo nombre de James Brown, noviembre de 2015, misma fábrica — Oveja Negra — para las ligadas menos ortodoxas. NBK, Killer Bee y Rorschach abrieron.","vitolas":[],"wrapper":"Habano de Ecuador"}]',
  `gamme_de` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","story":"\\"Die Sterbesakramente\\" — die Gründungslinie und diejenige, die den Ton der gesamten Bildsprache des Hauses vorgab. Kräftig, in der Oveja Negra gerollt.","vitolas":["Robusto","Toro","Petit Lancero"],"wrapper":"Oveja-Negra-Mischung"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","story":"Das Gegenstück zur Last Rites, im selben liturgischen Register. Blätter aus Nicaragua, Honduras, San Andrés und Ecuador.","vitolas":["Robusto","Toro"],"wrapper":"Oveja-Negra-Mischung"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","story":"Der Heilige Tod der mexikanischen Volksfrömmigkeit, von James Brown selbst gezeichnet. Das Haus führt seine Bildsprache zu Ende, statt sie nur anzudeuten.","vitolas":["Robusto","Toro"],"wrapper":"Oveja-Negra-Mischung"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","story":"James Browns zweiter Name, November 2015, dieselbe Fabrik — Oveja Negra — für die weniger orthodoxen Blends. NBK, Killer Bee und Rorschach eröffneten.","vitolas":[],"wrapper":"Ecuadorianisches Habano"}]',
  `gamme_zh` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","story":"「临终圣事」——奠基之作，也为这家的整套图像学定下了基调。浓烈，于 Oveja Negra 卷制。","vitolas":["Robusto","Toro","Petit Lancero"],"wrapper":"Oveja Negra 配方"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","story":"Last Rites 的对照款，属同一套礼拜语汇。烟叶来自尼加拉瓜、洪都拉斯、圣安德烈斯与厄瓜多尔。","vitolas":["Robusto","Toro"],"wrapper":"Oveja Negra 配方"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","story":"墨西哥民间信仰中的「圣死神」，由 James Brown 亲手绘制。这家把自己的图像学做到底，而非仅止于暗示。","vitolas":["Robusto","Toro"],"wrapper":"Oveja Negra 配方"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","story":"詹姆斯·布朗的第二个名字，2015年11月，同一家工厂——Oveja Negra——用于不那么正统的配方。NBK、Killer Bee 与 Rorschach 打头阵。","vitolas":[],"wrapper":"厄瓜多尔 Habano"}]',
  `gamme_ar` = '[{"name":"Last Rites","color":"#2E2018","force":"Full","story":"«الطقوس الأخيرة» — السلسلة المؤسِّسة، وهي التي أعطت نبرتها لكامل أيقونوغرافيا الدار. قويّة، وملفوفة في أوبيخا نيغرا.","vitolas":["Robusto","Toro","Petit Lancero"],"wrapper":"مزيج أوبيخا نيغرا"},{"name":"Salvation","color":"#4A2C1A","force":"Medium-Full","story":"نظيرة «لاست رايتس»، في السجلّ الطقسي نفسه. أوراق من نيكاراغوا وهندوراس وسان أندريس والإكوادور.","vitolas":["Robusto","Toro"],"wrapper":"مزيج أوبيخا نيغرا"},{"name":"Santa Muerte","color":"#3A2A20","force":"Full","story":"«الموت المقدّس» في التديّن الشعبي المكسيكي، من رسم جيمس براون نفسه. تمضي الدار بصورها إلى منتهاها بدل الاكتفاء بالتلميح.","vitolas":["Robusto","Toro"],"wrapper":"مزيج أوبيخا نيغرا"},{"name":"Black Works Studio","color":"#1F1F1F","force":"Full","story":"الاسم الثاني لجيمس براون، تشرين الثاني/نوفمبر 2015، المصنع نفسه — Oveja Negra — للمزجات الأقلّ تقليديةً. افتتحها NBK وKiller Bee وRorschach.","vitolas":[],"wrapper":"هابانو إكوادوري"}]',
