-- ── Cuban Crafters ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''atlas le note mais ne s''y trompe pas — la fiche est nicaraguayenne parce que les cigares se font à Estelí. Le recensement la classait aux États-Unis, à l''adresse de la boutique.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''atlas le note mais ne s''y trompe pas — la fiche est nicaraguayenne parce que les cigares se font à Estelí. Le recensement la classait aux États-Unis, à l''adresse de la boutique.', 'La fiche est nicaraguayenne parce que les cigares se font à Estelí.'), `history`),
  `history_en` = IF(LOCATE(CAST('The atlas notes it but is not misled — this entry is Nicaraguan because the cigars are made in Estelí. The census filed it under the United States, at the shop''s address.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The atlas notes it but is not misled — this entry is Nicaraguan because the cigars are made in Estelí. The census filed it under the United States, at the shop''s address.', 'This entry is Nicaraguan because the cigars are made in Estelí.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El atlas lo anota pero no se confunde: esta ficha es nicaragüense porque los puros se hacen en Estelí. El censo la clasificaba en Estados Unidos, en la dirección de la tienda.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El atlas lo anota pero no se confunde: esta ficha es nicaragüense porque los puros se hacen en Estelí. El censo la clasificaba en Estados Unidos, en la dirección de la tienda.', 'Esta ficha es nicaragüense porque los puros se hacen en Estelí.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der Atlas vermerkt ihn, lässt sich aber nicht täuschen — dieser Eintrag ist nicaraguanisch, weil die Zigarren in Estelí gemacht werden. Die Bestandsaufnahme führte ihn unter den Vereinigten Staaten, unter der Adresse des Ladens.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der Atlas vermerkt ihn, lässt sich aber nicht täuschen — dieser Eintrag ist nicaraguanisch, weil die Zigarren in Estelí gemacht werden. Die Bestandsaufnahme führte ihn unter den Vereinigten Staaten, unter der Adresse des Ladens.', 'Dieser Eintrag ist nicaraguanisch, weil die Zigarren in Estelí gemacht werden.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集记下它，却不会被它误导——这一条目属于尼加拉瓜，因为雪茄是在埃斯特利做的。清点曾按店铺地址把它归入美国。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集记下它，却不会被它误导——这一条目属于尼加拉瓜，因为雪茄是在埃斯特利做的。清点曾按店铺地址把它归入美国。', '这一条目属于尼加拉瓜，因为雪茄是在埃斯特利做的。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('والأطلس يسجّله ولا ينخدع به — فالبطاقة نيكاراغوية لأنّ السيجار يُصنع في إستيلي. وكان الإحصاء قد صنّفها في الولايات المتحدة على عنوان المتجر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'والأطلس يسجّله ولا ينخدع به — فالبطاقة نيكاراغوية لأنّ السيجار يُصنع في إستيلي. وكان الإحصاء قد صنّفها في الولايات المتحدة على عنوان المتجر.', 'والبطاقة نيكاراغوية لأنّ السيجار يُصنع في إستيلي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuban Crafters';

-- ── Cuban Stock Cigar Co. ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('qui a vingt ans quand l''atlas la rencontre, et qui vient de changer d''échelle' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'qui a vingt ans quand l''atlas la rencontre, et qui vient de changer d''échelle', 'qui vient de changer d''échelle après vingt ans d''existence'), `history`),
  `history_en` = IF(LOCATE(CAST('that is twenty years old when this atlas meets it, and that has just changed scale' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'that is twenty years old when this atlas meets it, and that has just changed scale', 'that has just changed scale after twenty years of existence'), `history_en`),
  `history_es` = IF(LOCATE(CAST('que tiene veinte años cuando este atlas la encuentra, y que acaba de cambiar de escala' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'que tiene veinte años cuando este atlas la encuentra, y que acaba de cambiar de escala', 'que acaba de cambiar de escala tras veinte años de existencia'), `history_es`),
  `history_de` = IF(LOCATE(CAST('das zwanzig Jahre alt ist, als dieser Atlas ihm begegnet, und das gerade den Maßstab gewechselt hat' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'das zwanzig Jahre alt ist, als dieser Atlas ihm begegnet, und das gerade den Maßstab gewechselt hat', 'das nach zwanzig Jahren Bestehen gerade den Maßstab gewechselt hat'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集遇见它时已二十岁，且刚刚换了量级' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集遇见它时已二十岁，且刚刚换了量级', '历经二十年后刚刚换了量级'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كان عمرها عشرون سنة حين التقاها هذا الأطلس، وكانت قد غيّرت حجمها لتوّها' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كان عمرها عشرون سنة حين التقاها هذا الأطلس، وكانت قد غيّرت حجمها لتوّها', 'غيّرت حجمها لتوّها بعد عشرين سنة من وجودها'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Cuban Stock Cigar Co.';

-- ── Curivari ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(', et cet atlas ne l''invente pas' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, ', et cet atlas ne l''invente pas', ''), `history`),
  `history_en` = IF(LOCATE(CAST(', and this atlas does not invent one' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, ', and this atlas does not invent one', ''), `history_en`),
  `history_es` = IF(LOCATE(CAST(', y este atlas no lo inventa' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ', y este atlas no lo inventa', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST(', und dieser Atlas erfindet keinen' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, ', und dieser Atlas erfindet keinen', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('，本图集也不予杜撰' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '，本图集也不予杜撰', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('، وهذا الأطلس لا يخترع اسمًا' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '، وهذا الأطلس لا يخترع اسمًا', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Curivari';

-- ── De Los Reyes Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Arsen, que le recensement de cet atlas listait comme une maison absente, est une marque' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Arsen, que le recensement de cet atlas listait comme une maison absente, est une marque', 'Arsen est une marque'), `history`),
  `history_en` = IF(LOCATE(CAST('Arsen, which this atlas''s census listed as a missing house, is a brand' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Arsen, which this atlas''s census listed as a missing house, is a brand', 'Arsen is a brand'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Arsen, que el censo de este atlas listaba como una casa ausente, es una marca' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Arsen, que el censo de este atlas listaba como una casa ausente, es una marca', 'Arsen es una marca'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Arsen, das die Bestandsaufnahme dieses Atlas als fehlendes Haus führte, ist eine Marke' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Arsen, das die Bestandsaufnahme dieses Atlas als fehlendes Haus führte, ist eine Marke', 'Arsen ist eine Marke'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Arsen 曾被本图集的普查列为「缺席的老号」，它确是' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Arsen 曾被本图集的普查列为「缺席的老号」，它确是', 'Arsen 是'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أمّا أرسِن، التي أدرجها إحصاءُ هذا الأطلس بين الدور الغائبة، فهي علامة' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أمّا أرسِن، التي أدرجها إحصاءُ هذا الأطلس بين الدور الغائبة، فهي علامة', 'Arsen علامة'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'De Los Reyes Cigars';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('C''est à ce titre qu''elle figure ici, et non parce qu''un recensement s''est trompé : une marque conçue par un tiers et roulée dans cette maison est exactement ce que cet atlas s''oblige à nommer — même cas que Zino' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'C''est à ce titre qu''elle figure ici, et non parce qu''un recensement s''est trompé : une marque conçue par un tiers et roulée dans cette maison est exactement ce que cet atlas s''oblige à nommer — même cas que Zino', 'Elle figure ici à ce titre : une marque conçue par un tiers et roulée dans cette maison — même cas que Zino'), `history`),
  `history_en` = IF(LOCATE(CAST(', and not because a census got something wrong: a brand conceived by an outsider and rolled in this house is exactly what this atlas obliges itself to name — the same case' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, ', and not because a census got something wrong: a brand conceived by an outsider and rolled in this house is exactly what this atlas obliges itself to name — the same case', ': a brand conceived by an outsider and rolled in this house — the same case'), `history_en`),
  `history_es` = IF(LOCATE(CAST(', y no porque un censo se equivocara: una marca concebida por un tercero y liada en esta casa es exactamente lo que este atlas se obliga a nombrar — el mismo caso' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ', y no porque un censo se equivocara: una marca concebida por un tercero y liada en esta casa es exactamente lo que este atlas se obliga a nombrar — el mismo caso', ': una marca concebida por un tercero y liada en esta casa — el mismo caso'), `history_es`),
  `history_de` = IF(LOCATE(CAST(', und nicht weil eine Bestandsaufnahme sich geirrt hätte: eine von außen ersonnene, in diesem Haus gerollte Marke ist genau das, was dieser Atlas zu benennen verpflichtet ist — derselbe Fall' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, ', und nicht weil eine Bestandsaufnahme sich geirrt hätte: eine von außen ersonnene, in diesem Haus gerollte Marke ist genau das, was dieser Atlas zu benennen verpflichtet ist — derselbe Fall', ': eine von außen ersonnene, in diesem Haus gerollte Marke — derselbe Fall'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('，而非因为普查出了差错：由外人构思、在这家老号卷制的牌子，恰恰是本图集必须点明的那一类——与' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '，而非因为普查出了差错：由外人构思、在这家老号卷制的牌子，恰恰是本图集必须点明的那一类——与', '：由外人构思、在这家老号卷制的牌子——与'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('، لا لأنّ إحصاءً أخطأ: فعلامةٌ يتصوّرها طرفٌ ثالث وتُلفّ في هذه الدار هي بالضبط ما يُلزم هذا الأطلسُ نفسَه بتسميته' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '، لا لأنّ إحصاءً أخطأ: فعلامةٌ يتصوّرها طرفٌ ثالث وتُلفّ في هذه الدار هي بالضبط ما يُلزم هذا الأطلسُ نفسَه بتسميته', ': علامةٌ يتصوّرها طرفٌ ثالث وتُلفّ في هذه الدار'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'De Los Reyes Cigars';

UPDATE `brands` SET
  `gamme` = '[{"name":"Saga","color":"#6B4226","force":"Medium","story":"La marque que la maison exporte le plus. Elle décline plusieurs séries — Golden Age, Blend No. 7, Short Tales — sur les tabacs des champs de Leo Reyes.","vitolas":["Robusto","Toro","Corona","Lancero"],"wrapper":"Assemblages dominicains"},{"name":"Saga Blend No. 7","color":"#5A3A24","force":"Full","story":"La série de la Saga que l''on cherche le plus souvent par son nom. Cape brésilienne de la ferme familiale, sous-cape Habano dominicaine, tripe dominicaine et centraméricaine, en trois formats seulement.","vitolas":["Robusto","Perfecto","Toro Gordo"],"wrapper":"Cape brésilienne dite Cobra, de la ferme Reyes"},{"name":"Don Julio","color":"#7A4A2C","force":"Medium-Full","story":"Le nom d''un homme : Don Julio Samuel Reyes Fermín, cultivateur de la troisième génération. Entièrement dominicaine, sur les tabacs des champs familiaux du Cibao. Deux lignes — Punta Espada (2014) et Sang Bleu (2024), première nouveauté de production régulière en dix ans.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Tabacs dominicains du Cibao"},{"name":"Augusto Reyes","color":"#8B5A2B","force":"Medium-Full","story":"Le nom du fondateur, sur la gamme qui reste la plus attachée aux tabacs de la maison.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Assemblages dominicains"},{"name":"Arsen","color":"#4A3728","force":"Medium","story":"Conçue au dehors, roulée ici. Arsen Gasparian l''a lancée en 2010 — il éditait la revue russe Hecho a Mano — et elle emploie la cape de la ferme de Navarrete.","vitolas":["Robusto","Toro"],"wrapper":"Cape de Navarrete"}]',
  `gamme_en` = '[{"name":"Saga","color":"#6B4226","force":"Medium","story":"The brand the house exports most. It runs several series — Golden Age, Blend No. 7, Short Tales — on tobacco from the fields of Leo Reyes.","vitolas":["Robusto","Toro","Corona","Lancero"],"wrapper":"Dominican blends"},{"name":"Saga Blend No. 7","color":"#5A3A24","force":"Full","story":"The Saga series most often looked up by name. A Brazilian wrapper from the family farm, a Dominican Habano binder, Dominican and Central American filler, in three sizes only.","vitolas":["Robusto","Perfecto","Toro Gordo"],"wrapper":"Brazilian Cobra wrapper from the Reyes farm"},{"name":"Don Julio","color":"#7A4A2C","force":"Medium-Full","story":"A man''s name: Don Julio Samuel Reyes Fermín, a third-generation grower. Entirely Dominican, on tobacco from the family fields in the Cibao valley. Two lines — Punta Espada (2014) and Sang Bleu (2024), the first new regular-production line in ten years.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Dominican tobaccos from the Cibao"},{"name":"Augusto Reyes","color":"#8B5A2B","force":"Medium-Full","story":"The founder''s name, on the line that stays closest to the house''s own tobacco.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Dominican blends"},{"name":"Arsen","color":"#4A3728","force":"Medium","story":"Conceived outside, rolled here. Arsen Gasparian launched it in 2010 — he published the Russian magazine Hecho a Mano — and it uses the wrapper from the Navarrete farm.","vitolas":["Robusto","Toro"],"wrapper":"Navarrete wrapper"}]',
  `gamme_es` = '[{"name":"Saga","color":"#6B4226","force":"Medium","story":"La marca que la casa más exporta. Declina varias series — Golden Age, Blend No. 7, Short Tales — sobre los tabacos de los campos de Leo Reyes.","vitolas":["Robusto","Toro","Corona","Lancero"],"wrapper":"Ligas dominicanas"},{"name":"Saga Blend No. 7","color":"#5A3A24","force":"Full","story":"La serie de la Saga que más se busca por su nombre. Capa brasileña de la finca familiar, capote Habano dominicano, tripa dominicana y centroamericana, en solo tres formatos.","vitolas":["Robusto","Perfecto","Toro Gordo"],"wrapper":"Capa brasileña llamada Cobra, de la finca Reyes"},{"name":"Don Julio","color":"#7A4A2C","force":"Medium-Full","story":"El nombre de un hombre: Don Julio Samuel Reyes Fermín, cultivador de la tercera generación. Enteramente dominicana, sobre los tabacos de los campos familiares del Cibao. Dos líneas — Punta Espada (2014) y Sang Bleu (2024), primera novedad de producción regular en diez años.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Tabacos dominicanos del Cibao"},{"name":"Augusto Reyes","color":"#8B5A2B","force":"Medium-Full","story":"El nombre del fundador, en la gama que sigue más apegada a los tabacos de la casa.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Ligas dominicanas"},{"name":"Arsen","color":"#4A3728","force":"Medium","story":"Concebida fuera, liada aquí. Arsen Gasparian la lanzó en 2010 — editó la revista rusa Hecho a Mano — y usa la capa de la finca de Navarrete.","vitolas":["Robusto","Toro"],"wrapper":"Capa de Navarrete"}]',
  `gamme_de` = '[{"name":"Saga","color":"#6B4226","force":"Medium","story":"Die Hauptexportmarke des Hauses. Sie führt mehrere Serien — Golden Age, Blend No. 7, Short Tales — auf Tabaken von den Feldern von Leo Reyes.","vitolas":["Robusto","Toro","Corona","Lancero"],"wrapper":"Dominikanische Blends"},{"name":"Saga Blend No. 7","color":"#5A3A24","force":"Full","story":"Die Saga-Serie, die am häufigsten namentlich gesucht wird. Brasilianisches Deckblatt vom Familienhof, dominikanisches Habano-Umblatt, dominikanische und mittelamerikanische Einlage, in nur drei Formaten.","vitolas":["Robusto","Perfecto","Toro Gordo"],"wrapper":"Brasilianisches Cobra-Deckblatt aus der Reyes-Farm"},{"name":"Don Julio","color":"#7A4A2C","force":"Medium-Full","story":"Der Name eines Mannes: Don Julio Samuel Reyes Fermín, Anbauer der dritten Generation. Ganz dominikanisch, auf Tabaken von den Familienfeldern im Cibao-Tal. Zwei Linien — Punta Espada (2014) und Sang Bleu (2024), die erste reguläre Neuheit seit zehn Jahren.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Dominikanische Tabake aus dem Cibao"},{"name":"Augusto Reyes","color":"#8B5A2B","force":"Medium-Full","story":"Der Name des Gründers, auf der Linie, die den eigenen Tabaken des Hauses am nächsten bleibt.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Dominikanische Blends"},{"name":"Arsen","color":"#4A3728","force":"Medium","story":"Draußen ersonnen, hier gerollt. Arsen Gasparian brachte sie 2010 heraus — er gab die russische Zeitschrift Hecho a Mano heraus — und sie verwendet das Deckblatt der Farm Navarrete.","vitolas":["Robusto","Toro"],"wrapper":"Deckblatt aus Navarrete"}]',
  `gamme_zh` = '[{"name":"Saga","color":"#6B4226","force":"Medium","story":"这家老号的主力出口牌子。它分出若干系列——Golden Age、Blend No. 7、Short Tales——用的是莱奥·雷耶斯田里的烟叶。","vitolas":["Robusto","Toro","Corona","Lancero"],"wrapper":"多米尼加配方"},{"name":"Saga Blend No. 7","color":"#5A3A24","force":"Full","story":"Saga 中常被人按名字搜寻的一个系列。茄衣为家族农场的巴西烟叶，茄套是多米尼加 Habano，填充为多米尼加与中美洲烟叶，仅出三种尺寸。","vitolas":["Robusto","Perfecto","Toro Gordo"],"wrapper":"来自雷耶斯农场的巴西 Cobra 茄衣"},{"name":"Don Julio","color":"#7A4A2C","force":"Medium-Full","story":"一个人的名字：堂胡利奥·萨穆埃尔·雷耶斯·费尔明，家族第三代种植者。全部使用家族在锡瓦奥河谷田里的多米尼加烟叶。两条线——Punta Espada（2014）与 Sang Bleu（2024），后者是十年来第一款常规生产的新品。","vitolas":["Robusto","Toro","Churchill"],"wrapper":"锡瓦奥河谷的多米尼加烟叶"},{"name":"Augusto Reyes","color":"#8B5A2B","force":"Medium-Full","story":"创始人的名字，用在最贴近本号自有烟叶的那一系。","vitolas":["Robusto","Toro","Churchill"],"wrapper":"多米尼加配方"},{"name":"Arsen","color":"#4A3728","force":"Medium","story":"在外构思，在此卷制。阿尔森·加斯帕良于2010年推出它——他曾出版俄文杂志《Hecho a Mano》——它使用纳瓦雷特农场的茄衣。","vitolas":["Robusto","Toro"],"wrapper":"纳瓦雷特茄衣"}]',
  `gamme_ar` = '[{"name":"Saga","color":"#6B4226","force":"Medium","story":"العلامة التي تصدّرها الدار أكثر من غيرها. وتتفرّع إلى سلاسل عدّة — غولدن إيج، وبلند رقم 7، وشورت تيلز — على أتبغة حقول ليو رييس.","vitolas":["Robusto","Toro","Corona","Lancero"],"wrapper":"مزجات دومينيكية"},{"name":"Saga Blend No. 7","color":"#5A3A24","force":"Full","story":"سلسلة ساغا التي يُبحث عنها باسمها أكثر من سواها. غلاف برازيلي من مزرعة العائلة، ورباط هابانو دومينيكي، وحشوة دومينيكية ومن أمريكا الوسطى، في ثلاثة قياسات فقط.","vitolas":["Robusto","Perfecto","Toro Gordo"],"wrapper":"غلاف برازيلي يُسمّى كوبرا، من مزرعة رييس"},{"name":"Don Julio","color":"#7A4A2C","force":"Medium-Full","story":"اسم رجل: دون خوليو صامويل رييس فيرمين، مزارع من الجيل الثالث. دومينيكية بالكامل، على أتبغة حقول العائلة في وادي سيباو. ولها خطّان — بونتا إسبادا (2014) وسانغ بلو (2024)، أوّل جديد في الإنتاج المنتظم منذ عشر سنوات.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"أتبغة دومينيكية من سيباو"},{"name":"Augusto Reyes","color":"#8B5A2B","force":"Medium-Full","story":"اسم المؤسّس، على الخطّ الأوثق صلة بأتبغة الدار نفسها.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"مزجات دومينيكية"},{"name":"Arsen","color":"#4A3728","force":"Medium","story":"تُصوّرت في الخارج وتُلفّ هنا. أطلقها أرسِن غاسباريان سنة 2010 — وكان ينشر المجلة الروسية Hecho a Mano — وهي تستعمل غلاف مزرعة نافاريتي.","vitolas":["Robusto","Toro"],"wrapper":"غلاف من نافاريتي"}]',
  `updated_at` = NOW()
 WHERE `name` = 'De Los Reyes Cigars';

-- ── Debonaire House ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('dont l''atlas porte la fiche : c''est là que tout est roulé, sous la supervision de Zanghi, et la fiche De Los Reyes le nommait déjà comme travail à façon sans que la maison ait la sienne.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'dont l''atlas porte la fiche : c''est là que tout est roulé, sous la supervision de Zanghi, et la fiche De Los Reyes le nommait déjà comme travail à façon sans que la maison ait la sienne.', 'qui a sa propre fiche : c''est là que tout est roulé, sous la supervision de Zanghi.'), `history`),
  `history_en` = IF(LOCATE(CAST('whose entry this atlas carries: that is where everything is rolled, under Zanghi''s supervision, and the De Los Reyes entry already named it as contract work without the house having its own.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'whose entry this atlas carries: that is where everything is rolled, under Zanghi''s supervision, and the De Los Reyes entry already named it as contract work without the house having its own.', 'which has its own entry: that is where everything is rolled, under Zanghi''s supervision.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('cuya ficha lleva este atlas: allí se lía todo, bajo la supervisión de Zanghi, y la ficha De Los Reyes ya la nombraba como trabajo a maquila sin que la casa tuviera la suya.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'cuya ficha lleva este atlas: allí se lía todo, bajo la supervisión de Zanghi, y la ficha De Los Reyes ya la nombraba como trabajo a maquila sin que la casa tuviera la suya.', 'que tiene su propia ficha: allí se lía todo, bajo la supervisión de Zanghi.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('deren Eintrag dieser Atlas führt: Dort wird alles gerollt, unter Zanghis Aufsicht, und der De-Los-Reyes-Eintrag nannte es bereits als Lohnfertigung, ohne dass das Haus einen eigenen hatte.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'deren Eintrag dieser Atlas führt: Dort wird alles gerollt, unter Zanghis Aufsicht, und der De-Los-Reyes-Eintrag nannte es bereits als Lohnfertigung, ohne dass das Haus einen eigenen hatte.', 'die einen eigenen Eintrag hat: Dort wird alles gerollt, unter Zanghis Aufsicht.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集载有该厂词条：一切都在那里、在赞吉的监督下卷制，而 De Los Reyes 词条早已把它列为代工，只是这家公司自己还没有词条。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集载有该厂词条：一切都在那里、在赞吉的监督下卷制，而 De Los Reyes 词条早已把它列为代工，只是这家公司自己还没有词条。', '该厂有自己的词条：一切都在那里、在赞吉的监督下卷制。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('الذي يحمل هذا الأطلس بطاقته: هناك يُلفّ كلّ شيء، تحت إشراف زانغي، وكانت بطاقة De Los Reyes تسمّيها أصلًا عملًا بالوكالة دون أن تكون للدار بطاقتها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'الذي يحمل هذا الأطلس بطاقته: هناك يُلفّ كلّ شيء، تحت إشراف زانغي، وكانت بطاقة De Los Reyes تسمّيها أصلًا عملًا بالوكالة دون أن تكون للدار بطاقتها.', 'الذي له بطاقته الخاصة: هناك يُلفّ كلّ شيء، تحت إشراف زانغي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Debonaire House';

-- ── Don Diego ──
UPDATE `brands` SET
  `source` = IF(LOCATE(CAST(' — le champ de date disait « années 1960 — La Romana » et mélangeait les deux ; corrigé par la migration 198' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' — le champ de date disait « années 1960 — La Romana » et mélangeait les deux ; corrigé par la migration 198', ''), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Don Diego';

-- ── Dona Flor ──
UPDATE `brands` SET
  `source` = IF(LOCATE(CAST(' — la fiche a été corrigée par la migration 193' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' — la fiche a été corrigée par la migration 193', ''), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Dona Flor';

-- ── Drew Estate ──
UPDATE `brands` SET
  `gamme` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"La gamme infusée qui a fait connaître la maison — arômes de thé, herbes botaniques, essence florale. Format Robusto (54 x 127mm). Cape d''Indonésie sur un assemblage que Drew Estate ne détaille pas. C''est le cigare qui a fait entrer dans le genre des fumeurs que la puissance des assemblages traditionnels aurait écartés. Contesté chez les puristes, adoré de ses amateurs.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonésie"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"L''autre visage de Drew Estate — le plus sérieux, le plus recherché. Cape Connecticut Broadleaf Habano sur triple ligero nicaraguayen. Notes de café ristretto, cacao amer, mûre. La Flying Pig, perfecto court et trapu, est le format le plus rare et le plus cher de la gamme.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Créée par les torcedores eux-mêmes — les ouvriers de l''usine voulaient un cigare aussi bon que la Liga Privada à un prix qu''ils pouvaient payer. Assemblage proche du No.9, sous une cape d''Équateur moins coûteuse. Notes de chocolat, café, poivre.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Équateur"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"Le cigare de Willy Herrera, l''assembleur d''El Titan de Bronze à Miami engagé en 2011, lancé au début de 2013 sur une recette composée lors de sa première visite à Estelí.","vitolas":[],"wrapper":"Habano d''Équateur"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Du tabac de Kentucky séché à la fumée de bois, comme celui des pipes, dans un cigare roulé à Estelí. Une ligne, pas une maison.","vitolas":[],"wrapper":"Kentucky séché au feu"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — le cigare que les rouleurs se font, dit la maison : broadleaf, rustique, un seul format au départ.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — la version corsée d''Herrera Estelí, cape San Andrés.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"Ligne infusée : selon Corona Cigar Co., des épices d''Europe et d''Asie du Sud-Est, du vin et du rhum sur des tabacs du Honduras et du Nicaragua, avec, d''après CigarPlace, quatre mois d''infusion puis un vieillissement en armoires de cèdre. En octobre 2026, Corona Cigar Co. en affiche sept déclinaisons (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) sous des capes Connecticut Shade, Habano, Sumatra ou Cameroun, Cigars Direct donne le cigarillo Clove Tiki roulé à la main, et le catalogue en ligne de Drew Estate ne la liste pas.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Blackened","color":"#4A3728","force":null,"story":"Collaboration entre Drew Estate, James Hetfield (Metallica) et Rob Dietrich (whisky Blackened), dit la maison. La M81, sortie le 18 octobre 2022 d''après un article de presse, associe une cape San Andrés maduro à un liant Connecticut Broadleaf maduro, en Corona, Robusto, Toro et Corona Doble ; la S84 Shade to Black, début 2024 selon Corona Cigar Co., passe à une cape Connecticut Shade d''Équateur, et drewestate.com présente ces deux expressions en octobre 2026.","vitolas":[],"wrapper":"San Andrés, Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"Lancée en 2006, quand la maison faisait ses débuts dans le cigare non infusé, puis abandonnée, elle a été annoncée de retour le 9 novembre 2023 en Connecticut Shade sur liant et tripes nicaraguayens, pour les détaillants en ligne du réseau Drew Diplomat. Drew Estate y a ajouté un Habano pour Cigars International en août 2024 et un Maduro San Andrés pour ses comptes DDDP le 1er novembre 2024, tous roulés à La Gran Fabrica en Robusto, Toro et Churchill ; en octobre 2026, la page produits de drewestate.com ne la liste pas parmi ses lignes.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"Cigares vendus en bottes de 20 ou 25 : communiqué de la maison du 29 juin 2018, présentation à l''IPCPR en juillet 2018, quatre déclinaisons (Sweet à cape Habano, Maduro, Shade, Sun Grown) sur liant et tripes d''Indonésie, roulées à La Gran Fabrica en Robusto, Toro, Churchill et Gordito. En octobre 2026, drewestate.com la présente avec Maduro, Sweet, Shade et Sun Grown.","vitolas":[],"wrapper":"Non divulguée"}]',
  `gamme_en` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"The infused best-seller — aromas of tea, botanical herbs, floral essence. Robusto format (54 x 127mm). The cigar that introduced millions of Americans to cigars without intimidating them with traditional blend power. Indonesian wrapper over Drew Estate proprietary blend. Controversial among purists, adored by fans.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesian"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"The other face of Drew Estate — the most serious, the most sought after. Connecticut Broadleaf Habano wrapper over Nicaraguan triple ligero. Ristretto coffee, bitter cocoa, blackberry. The Flying Pig, a short stubby perfecto, is the rarest and dearest shape in the range.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Created by the torcedores themselves — factory workers who wanted a cigar as good as Liga Privada at an accessible price. Blend close to the No.9, less expensive Ecuadorian wrapper. Notes of chocolate, coffee, pepper. The most successful worker rebellion in the industry.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuadorian"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"Willy Herrera''s cigar — the El Titan de Bronze blender from Miami, hired in 2011 — launched in early 2013 on a recipe composed during his first visit to Estelí.","vitolas":[],"wrapper":"Ecuadorian Habano"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Kentucky tobacco cured over wood smoke, as for pipes, in a cigar rolled in Estelí. A line, not a house.","vitolas":[],"wrapper":"Fire-cured Kentucky"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — the cigar rollers make for themselves, the house says: broadleaf, rustic, a single size at first.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — the full-bodied version of Herrera Estelí, San Andrés wrapper.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"Infused line: according to Corona Cigar Co., spices from Europe and South-East Asia, wine and rum on tobaccos from Honduras and Nicaragua, with, according to CigarPlace, four months of infusion followed by ageing in cedar cabinets. In October 2026, Corona Cigar Co. lists seven versions of it (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) under Connecticut Shade, Habano, Sumatra or Cameroon wrappers, Cigars Direct gives the Clove Tiki cigarillo as hand-rolled, and Drew Estate''s online catalogue does not list it.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Blackened","color":"#4A3728","force":null,"story":"A collaboration between Drew Estate, James Hetfield (Metallica) and Rob Dietrich (Blackened whisky), says the company. The M81, released on 18 October 2022 according to a press article, pairs a maduro San Andrés wrapper with a maduro Connecticut Broadleaf binder, in Corona, Robusto, Toro and Corona Doble; the S84 Shade to Black, in early 2024 according to Corona Cigar Co., switches to an Ecuadorian Connecticut Shade wrapper, and drewestate.com presents these two expressions in October 2026.","vitolas":[],"wrapper":"San Andrés, Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"Launched in 2006, when the company was making its debut in non-infused cigars, then abandoned, it was announced as returning on 9 November 2023 in Connecticut Shade over a Nicaraguan binder and filler, for the online retailers of the Drew Diplomat network. Drew Estate added to it a Habano for Cigars International in August 2024 and a San Andrés Maduro for its DDDP accounts on 1 November 2024, all rolled at La Gran Fabrica in Robusto, Toro and Churchill; in October 2026, the products page of drewestate.com does not list it among its lines.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"Cigars sold in bundles of 20 or 25: press release from the company dated 29 June 2018, presentation at the IPCPR in July 2018, four versions (Sweet with a Habano wrapper, Maduro, Shade, Sun Grown) on an Indonesian binder and filler, rolled at La Gran Fabrica in Robusto, Toro, Churchill and Gordito. In October 2026, drewestate.com presents it with Maduro, Sweet, Shade and Sun Grown.","vitolas":[],"wrapper":"Undisclosed"}]',
  `gamme_es` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"El superventas infusionado: aromas de té, hierbas botánicas, esencia floral. Robusto (54 x 127mm). El puro que introdujo a millones de estadounidenses en el cigarro sin asustarlos con la potencia de las ligas tradicionales. Capa indonesia sobre liga propia de Drew Estate. Controvertido entre los puristas, adorado por sus fieles.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesia"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"La otra cara de Drew Estate: la más seria, la más buscada. Capa Connecticut Broadleaf Habano sobre triple ligero nicaragüense. Café ristretto, cacao amargo, mora. La Flying Pig, un perfecto corto y rechoncho, es el formato más raro y más caro de la gama.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Creada por los propios torcedores: los obreros de la fábrica querían un puro tan bueno como Liga Privada a precio accesible. Liga cercana a la del No.9, capa ecuatoriana más económica. Chocolate, café, pimienta. La revuelta obrera más lograda del sector.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"El puro de Willy Herrera, el ligador de El Titan de Bronze en Miami contratado en 2011, lanzado a principios de 2013 con una receta compuesta en su primera visita a Estelí.","vitolas":[],"wrapper":"Habano de Ecuador"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Tabaco de Kentucky curado al humo de leña, como el de las pipas, en un puro liado en Estelí. Una línea, no una casa.","vitolas":[],"wrapper":"Kentucky curado al fuego"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — el puro que los torcedores se hacen, dice la casa: broadleaf, rústico, un solo formato al principio.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — la versión fuerte de Herrera Estelí, capa San Andrés.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"Línea infusionada: según Corona Cigar Co., especias de Europa y del Sudeste Asiático, vino y ron sobre tabacos de Honduras y Nicaragua, con, según CigarPlace, cuatro meses de infusión y después una maduración en armarios de cedro. En octubre de 2026, Corona Cigar Co. muestra siete variantes de ella (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) con capas Connecticut Shade, Habano, Sumatra o Cameroun, Cigars Direct indica que el cigarillo Clove Tiki está enrollado a mano, y el catálogo en línea de Drew Estate no la incluye.","vitolas":[],"wrapper":"No divulgada"},{"name":"Blackened","color":"#4A3728","force":null,"story":"Colaboración entre Drew Estate, James Hetfield (Metallica) y Rob Dietrich (whisky Blackened), dice la casa. La M81, que salió el 18 de octubre de 2022 según un artículo de prensa, combina una capa San Andrés maduro con un capote Connecticut Broadleaf maduro, en Corona, Robusto, Toro y Corona Doble; la S84 Shade to Black, a principios de 2024 según Corona Cigar Co., pasa a una capa Connecticut Shade de Ecuador, y drewestate.com presenta estas dos expresiones en octubre de 2026.","vitolas":[],"wrapper":"San Andrés, Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"Lanzada en 2006, cuando la casa debutaba en el puro sin infusión, y luego abandonada, se anunció su regreso el 9 de noviembre de 2023 en Connecticut Shade sobre capote y tripa nicaragüenses, para los minoristas en línea de la red Drew Diplomat. Drew Estate le añadió un Habano para Cigars International en agosto de 2024 y un Maduro San Andrés para sus cuentas DDDP el 1 de noviembre de 2024, todos enrollados en La Gran Fabrica en Robusto, Toro y Churchill; en octubre de 2026, la página de productos de drewestate.com no la incluye entre sus líneas.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"Puros vendidos en bundles de 20 o 25: comunicado de la casa del 29 de junio de 2018, presentación en el IPCPR en julio de 2018, cuatro versiones (Sweet con capa Habano, Maduro, Shade, Sun Grown) sobre capote y tripa de Indonesia, enrolladas en La Gran Fabrica en Robusto, Toro, Churchill y Gordito. En octubre de 2026, drewestate.com la presenta con Maduro, Sweet, Shade y Sun Grown.","vitolas":[],"wrapper":"No divulgada"}]',
  `gamme_de` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"Der infundierte Bestseller — Tee, botanische Kräuter, blumige Essenz. Robusto (54 x 127 mm). Die Zigarre, die Millionen Amerikaner an die Zigarre heranführte, ohne sie mit der Kraft traditioneller Mischungen zu erschrecken. Indonesisches Deckblatt über hauseigener Drew-Estate-Mischung. Umstritten bei Puristen, geliebt von ihren Anhängern.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesien"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Das andere Gesicht von Drew Estate — das ernsteste, das begehrteste. Deckblatt Connecticut Broadleaf Habano über nicaraguanischem Triple Ligero. Ristretto, bittere Kakao, Brombeere. Die Flying Pig, ein kurzes, gedrungenes Perfecto, ist das seltenste und teuerste Format der Serie.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Von den Torcedores selbst geschaffen — die Arbeiter der Fabrik wollten eine Zigarre so gut wie die Liga Privada zu zugänglichem Preis. Mischung nah am No.9, günstigeres ecuadorianisches Deckblatt. Schokolade, Kaffee, Pfeffer. Die gelungenste Arbeiterrevolte der Branche.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"Die Zigarre von Willy Herrera, dem 2011 engagierten Blender von El Titan de Bronze in Miami, Anfang 2013 lanciert nach einem Rezept aus seinem ersten Besuch in Estelí.","vitolas":[],"wrapper":"Ecuadorianisches Habano"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Kentucky-Tabak, über Holzrauch getrocknet wie für Pfeifen, in einer in Estelí gerollten Zigarre. Eine Linie, kein Haus.","vitolas":[],"wrapper":"Feuergetrockneter Kentucky"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — die Zigarre, die sich die Roller selbst machen, sagt das Haus: Broadleaf, rustikal, anfangs ein einziges Format.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — die kräftige Version von Herrera Estelí, San-Andrés-Deckblatt.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"Infundierte Linie: laut Corona Cigar Co. Gewürze aus Europa und Südostasien, Wein und Rum auf Tabaken aus Honduras und Nicaragua, dazu laut CigarPlace vier Monate Infusion und anschließend Reifung in Zedernholzschränken. Im Oktober 2026 führt Corona Cigar Co. sieben Varianten davon auf (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) mit Deckblättern Connecticut Shade, Habano, Sumatra oder Cameroun; Cigars Direct nennt das Zigarillo Clove Tiki handgerollt, und der Online-Katalog von Drew Estate führt die Linie nicht auf.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Blackened","color":"#4A3728","force":null,"story":"Zusammenarbeit von Drew Estate, James Hetfield (Metallica) und Rob Dietrich (Whisky Blackened), sagt das Haus. Die M81, laut einem Presseartikel am 18. Oktober 2022 erschienen, kombiniert ein Deckblatt San Andrés maduro mit einem Umblatt Connecticut Broadleaf maduro, in Corona, Robusto, Toro und Corona Doble; die S84 Shade to Black, Anfang 2024 laut Corona Cigar Co., wechselt zu einem Deckblatt Connecticut Shade aus Ecuador, und drewestate.com präsentiert diese beiden Ausführungen im Oktober 2026.","vitolas":[],"wrapper":"San Andrés, Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"Im Jahr 2006 eingeführt, als das Haus seine Anfänge bei nicht infundierten Zigarren machte, dann aufgegeben, wurde sie am 9. November 2023 als Rückkehr angekündigt, in Connecticut Shade auf nicaraguanischem Umblatt und nicaraguanischer Einlage, für die Online-Händler des Netzes Drew Diplomat. Drew Estate fügte einen Habano für Cigars International im August 2024 und einen Maduro San Andrés für seine DDDP-Konten am 1. November 2024 hinzu, alle gerollt bei La Gran Fabrica in Robusto, Toro und Churchill; im Oktober 2026 führt die Produktseite von drewestate.com sie nicht unter ihren Linien auf.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"Zigarren, verkauft in Bundles zu 20 oder 25: Pressemitteilung des Hauses vom 29. Juni 2018, Vorstellung auf der IPCPR im Juli 2018, vier Varianten (Sweet mit Deckblatt Habano, Maduro, Shade, Sun Grown) auf Umblatt und Einlage aus Indonesien, gerollt bei La Gran Fabrica in Robusto, Toro, Churchill und Gordito. Im Oktober 2026 präsentiert drewestate.com die Linie mit Maduro, Sweet, Shade und Sun Grown.","vitolas":[],"wrapper":"Nicht angegeben"}]',
  `gamme_zh` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"浸香系列的畅销之作——茶、植物香草、花香精油。罗布图规格（54 x 127 毫米）。正是这支雪茄让数百万美国人接触雪茄，而不必先被传统配方的力度吓退。印尼茄衣，内裹 Drew Estate 自有配方。纯粹派对它争议不断，拥趸却爱之如命。","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"印尼"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Drew Estate 的另一副面孔——最正经，也最抢手。康涅狄格宽叶哈瓦那茄衣，内裹尼加拉瓜三重利赫罗。里斯特雷托咖啡、苦可可、黑莓。短而粗壮的 Flying Pig 是全系中最稀有也最昂贵的规格。","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"由卷制师们自己创制——厂里的工人想要一支像 Liga Privada 一样好、价格却够得着的雪茄。配方接近 No.9，改用更便宜的厄瓜多尔茄衣。巧克力、咖啡、胡椒。这是行业里最成功的一场工人起义。","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"厄瓜多尔"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"威利·埃雷拉的雪茄——他是迈阿密 El Titan de Bronze 的调配师，2011年受聘——2013年初推出，配方在他首次造访埃斯特利时调成。","vitolas":[],"wrapper":"厄瓜多尔 Habano"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"像烟斗烟草那样用木柴烟熏干燥的肯塔基烟叶，卷进一支埃斯特利制作的雪茄。是一条线，不是一家公司。","vitolas":[],"wrapper":"烟熏干燥的肯塔基烟叶"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013年——公司说这是卷工给自己做的雪茄：broadleaf，粗犷，起初只有一种尺寸。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015年——Herrera Estelí 的浓烈版，圣安德烈斯茄衣。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"浸渍型系列：据Corona Cigar Co.称，在洪都拉斯和尼加拉瓜的烟草上使用来自欧洲和东南亚的香料、葡萄酒和朗姆酒，另据CigarPlace称，浸渍四个月，随后在雪松木柜中陈化。2026年十月，Corona Cigar Co.列出该系列的七款（Kaya、Mother Earth、Nectar、Spice Torpedo、Spice Triple Corona、Vann Reef、Clove Tiki），茄衣为Connecticut Shade、Habano、Sumatra或Cameroun；Cigars Direct称Clove Tiki小雪茄为手工卷制；Drew Estate的在线目录未列出该系列。","vitolas":[],"wrapper":"未公开"},{"name":"Blackened","color":"#4A3728","force":null,"story":"Drew Estate、James Hetfield（Metallica）与Rob Dietrich（Blackened威士忌）的合作作品，据该公司称。M81据一篇媒体文章于2022年十月18日推出，搭配San Andrés maduro茄衣与Connecticut Broadleaf maduro茄套，有Corona、Robusto、Toro和Corona Doble规格；S84 Shade to Black据Corona Cigar Co.于2024年初推出，改用厄瓜多尔Connecticut Shade茄衣，drewestate.com于2026年十月展示这两款。","vitolas":[],"wrapper":"San Andrés，Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"于2006年推出，当时该公司刚开始涉足非浸渍雪茄，后被放弃；2023年十一月9日宣布回归，采用Connecticut Shade茄衣，配尼加拉瓜茄套和茄芯，面向Drew Diplomat网络的线上零售商。Drew Estate又为Cigars International添加了一款Habano（2024年八月），并为其DDDP账户添加了一款Maduro San Andrés（2024年十一月1日），均在La Gran Fabrica卷制，规格为Robusto、Toro和Churchill；2026年十月，drewestate.com的产品页面未将其列入其产品系列。","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"雪茄以每束20或25支的bundles形式出售：该公司于2018年六月29日发布新闻稿，并于2018年七月在IPCPR上亮相，共四款（Sweet配Habano茄衣、Maduro、Shade、Sun Grown），茄套和茄芯均来自印度尼西亚，在La Gran Fabrica卷制，规格为Robusto、Toro、Churchill和Gordito。2026年十月，drewestate.com展示该系列，含Maduro、Sweet、Shade和Sun Grown。","vitolas":[],"wrapper":"未公开"}]',
  `gamme_ar` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"الأكثر مبيعًا بين المنقوعات — شاي، أعشاب نباتية، خلاصة زهرية. روبوستو (54 × 127 مم). السيجار الذي عرّف ملايين الأمريكيين على التدخين دون أن يُفزعهم بقوّة الخلطات التقليدية. غلاف إندونيسي فوق خلطة خاصة بـDrew Estate. مثير للجدل عند المتشدّدين، محبوب عند أنصاره.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"إندونيسي"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"الوجه الآخر لـDrew Estate — الأكثر جدّية والأكثر طلبًا. غلاف كونيتيكت برودليف هابانو فوق ليغيرو نيكاراغوي ثلاثي. قهوة ريستريتو، كاكاو مرّ، توت أسود. أما الـFlying Pig، وهو بيرفيكتو قصير ممتلئ، فأندر قياسات المجموعة وأغلاها.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"أنشأها اللافّون أنفسهم — أراد عمّال المصنع سيجارًا بجودة الليغا بريفادا وبسعر في المتناول. خلطة قريبة من الـNo.9، بغلاف إكوادوري أقلّ كلفة. شوكولاتة، قهوة، فلفل. أنجح ثورة عمالية في هذه الصناعة.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"إكوادوري"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"سيجار ويلي إيريرا، مزّاج El Titan de Bronze في ميامي الذي استُقدم سنة 2011، أُطلق في مطلع 2013 على وصفة رُكّبت في زيارته الأولى لإستيلي.","vitolas":[],"wrapper":"هابانو إكوادوري"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"تبغ كنتاكي مجفَّف على دخان الخشب كتبغ الغليون، في سيجار يُلفّ في إستيلي. خطٌّ لا دار.","vitolas":[],"wrapper":"كنتاكي مجفَّف بالنار"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — السيجار الذي يصنعه اللفّافون لأنفسهم، كما تقول الدار: برودليف، خشن، قياس واحد في البداية.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — النسخة القويّة من Herrera Estelí، غلاف سان أندريس.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"خط مُنقَع: بحسب Corona Cigar Co.، توابل من أوروبا وجنوب شرق آسيا ونبيذ ورم على أنواع تبغ من هندوراس ونيكاراغوا، مع أربعة شهور من النقع ثم تعتيق في خزائن من خشب الأرز بحسب CigarPlace. وفي أكتوبر 2026 تعرض Corona Cigar Co. سبعة إصدارات منه (Kaya وMother Earth وNectar وSpice Torpedo وSpice Triple Corona وVann Reef وClove Tiki) بأغلفة خارجية Connecticut Shade أو Habano أو Sumatra أو Cameroun، وتذكر Cigars Direct أن سيجاريلو Clove Tiki ملفوف يدويًا، ولا يدرجه فهرس Drew Estate على الإنترنت.","vitolas":[],"wrapper":"غير معلن"},{"name":"Blackened","color":"#4A3728","force":null,"story":"تعاون بين Drew Estate وJames Hetfield (Metallica) وRob Dietrich (ويسكي Blackened)، كما تقول الشركة. أما M81، التي صدرت في 18 أكتوبر 2022 بحسب مقال صحفي، فتجمع بين غلاف خارجي San Andrés maduro ورابط Connecticut Broadleaf maduro، بمقاسات Corona وRobusto وToro وCorona Doble؛ وتنتقل S84 Shade to Black، في مطلع 2024 بحسب Corona Cigar Co.، إلى غلاف خارجي Connecticut Shade من الإكوادور، ويعرض drewestate.com هذين الإصدارين في أكتوبر 2026.","vitolas":[],"wrapper":"San Andrés، Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"أُطلقت في 2006، حين كانت الشركة في بداياتها مع السيجار غير المنقوع، ثم تُركت، ثم أُعلن عن عودتها في 9 نوفمبر 2023 بغلاف Connecticut Shade على رابط وحشوة من نيكاراغوا، لتجار التجزئة عبر الإنترنت في شبكة Drew Diplomat. وأضافت Drew Estate إليها Habano لصالح Cigars International في أغسطس 2024 وMaduro San Andrés لحسابات DDDP لديها في 1 نوفمبر 2024، وكلها ملفوفة في La Gran Fabrica بمقاسات Robusto وToro وChurchill؛ وفي أكتوبر 2026 لا تدرجها صفحة المنتجات في drewestate.com ضمن خطوطها.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"سيجار يُباع في bundles من 20 أو 25: بيان صحفي من الشركة بتاريخ 29 يونيو 2018، وعرض في IPCPR في يوليو 2018، وأربعة إصدارات (Sweet بغلاف Habano وMaduro وShade وSun Grown) على رابط وحشوة من إندونيسيا، ملفوفة في La Gran Fabrica بمقاسات Robusto وToro وChurchill وGordito. وفي أكتوبر 2026 يعرضها drewestate.com مع Maduro وSweet وShade وSun Grown.","vitolas":[],"wrapper":"غير معلن"}]',
  `source` = IF(LOCATE(CAST(' ; lot 5 : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 : ', ' ; '), `source`),
  `source` = IF(LOCATE(CAST(' ; lot 5 bis : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 bis : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Drew Estate';

-- ── Dunbarton Tobacco & Trust ──
UPDATE `brands` SET
  `source` = IF(LOCATE(CAST(' ; lot 5 bis : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 bis : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Dunbarton Tobacco & Trust';

-- ── Espinosa ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","story":"Une cape brésilienne sur tripe nicaraguayenne — l''une des rares réussites de la feuille de Bahia hors du Brésil. Fruits secs, poivre, une acidité qui vient de la cape.","vitolas":["Toro"],"wrapper":"Cape brésilienne"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","story":"Le style de la maison sans détour : corsé, poivré, franc. Roulé à La Zona, la manufacture que le fondateur a ouverte pour cesser de dépendre des autres.","vitolas":["Robusto"],"wrapper":"Habano de Nicaragua"},{"name":"601","color":"#7A2E1E","force":"Full","story":"La ligne née du temps d''EO Brands, gardée par Erik Espinosa après la séparation d''avec Eddie Ortega.","vitolas":[],"wrapper":"Habano d''Équateur"}]',
  `gamme_en` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","story":"A Brazilian wrapper over Nicaraguan filler — one of the rare successes of the Bahia leaf outside Brazil. Dried fruit, pepper, an acidity that comes from the wrapper.","vitolas":["Toro"],"wrapper":"Brazilian wrapper"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","story":"The house style without detours: full-bodied, peppery, frank. Rolled at La Zona, the factory the founder opened to stop depending on others.","vitolas":["Robusto"],"wrapper":"Nicaraguan Habano"},{"name":"601","color":"#7A2E1E","force":"Full","story":"The line born in the EO Brands days, kept by Erik Espinosa after the split from Eddie Ortega.","vitolas":[],"wrapper":"Ecuadorian Habano"}]',
  `gamme_es` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","story":"Una capa brasileña sobre tripa nicaragüense — uno de los escasos aciertos de la hoja de Bahía fuera de Brasil. Frutos secos, pimienta, una acidez que viene de la capa.","vitolas":["Toro"],"wrapper":"Capa brasileña"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","story":"El estilo de la casa sin rodeos: fuerte, apimentado, franco. Liado en La Zona, la fábrica que el fundador abrió para dejar de depender de los demás.","vitolas":["Robusto"],"wrapper":"Habano de Nicaragua"},{"name":"601","color":"#7A2E1E","force":"Full","story":"La línea nacida en tiempos de EO Brands, conservada por Erik Espinosa tras la separación de Eddie Ortega.","vitolas":[],"wrapper":"Habano de Ecuador"}]',
  `gamme_de` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","story":"Ein brasilianisches Deckblatt über nicaraguanischer Einlage — einer der seltenen Erfolge des Bahia-Blattes außerhalb Brasiliens. Trockenfrüchte, Pfeffer, eine Säure, die vom Deckblatt kommt.","vitolas":["Toro"],"wrapper":"Brasilianisches Deckblatt"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","story":"Der Hausstil ohne Umschweife: kräftig, pfeffrig, offen. Bei La Zona gerollt, der Manufaktur, die der Gründer eröffnete, um nicht länger von anderen abzuhängen.","vitolas":["Robusto"],"wrapper":"Habano aus Nicaragua"},{"name":"601","color":"#7A2E1E","force":"Full","story":"Die Linie aus der Zeit von EO Brands, von Erik Espinosa nach der Trennung von Eddie Ortega behalten.","vitolas":[],"wrapper":"Ecuadorianisches Habano"}]',
  `gamme_zh` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","story":"巴西茄衣配尼加拉瓜茄芯——巴伊亚烟叶在巴西之外少见的成功之一。干果、胡椒，以及来自茄衣的一份酸度。","vitolas":["Toro"],"wrapper":"巴西茄衣"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","story":"不绕弯子的家族风格：浓郁、带胡椒、直率。在「拉索纳」卷制——创始人为不再依赖他人而开设的工厂。","vitolas":["Robusto"],"wrapper":"尼加拉瓜哈瓦那种"},{"name":"601","color":"#7A2E1E","force":"Full","story":"诞生于 EO Brands 时期的系列，与埃迪·奥尔特加分道扬镳后由埃里克·埃斯皮诺萨保留。","vitolas":[],"wrapper":"厄瓜多尔 Habano"}]',
  `gamme_ar` = '[{"name":"Laranja Reserva","color":"#B8663A","force":"Medium-Full","story":"غلاف برازيلي فوق حشوة نيكاراغوية — أحد نجاحات ورقة باهيا النادرة خارج البرازيل. فواكه مجفّفة وفلفل وحموضة تأتي من الغلاف.","vitolas":["Toro"],"wrapper":"غلاف برازيلي"},{"name":"Espinosa Habano","color":"#8B4513","force":"Full","story":"أسلوب الدار بلا التفاف: قويّ، فلفلي، صريح. ملفوف في «لا سونا»، المصنع الذي افتتحه المؤسّس ليكفّ عن الاعتماد على غيره.","vitolas":["Robusto"],"wrapper":"هابانو نيكاراغوي"},{"name":"601","color":"#7A2E1E","force":"Full","story":"الخطّ الذي وُلد في زمن EO Brands، واحتفظ به إريك إسبينوسا بعد الانفصال عن إدي أورتيغا.","vitolas":[],"wrapper":"هابانو إكوادوري"}]',
  `source` = IF(LOCATE(CAST(' ; lot 5 : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Espinosa';

-- ── Fable Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(' L''atlas l''écrit au retour, pas au départ.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, ' L''atlas l''écrit au retour, pas au départ.', ''), `history`),
  `history_en` = IF(LOCATE(CAST(' This atlas writes it at the return, not at the start.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, ' This atlas writes it at the return, not at the start.', ''), `history_en`),
  `history_es` = IF(LOCATE(CAST(' Este atlas la escribe al regreso, no a la salida.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ' Este atlas la escribe al regreso, no a la salida.', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST(' Dieser Atlas schreibt es bei der Rückkehr, nicht beim Start.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, ' Dieser Atlas schreibt es bei der Rückkehr, nicht beim Start.', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集在回归时写它，而非出发时。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集在回归时写它，而非出发时。', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST(' يكتبها هذا الأطلس عند العودة لا عند الانطلاق.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, ' يكتبها هذا الأطلس عند العودة لا عند الانطلاق.', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Fable Cigars';

