-- ── Foundation Cigar Company ──
UPDATE `brands` SET
  `gamme` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"L''assemblage fondateur de 2015, nommé d''après une satire coloniale transmise oralement pendant des siècles, roulé alors à l''usine TABSA, aujourd''hui Aganorsa Leaf. En mars 2024, Foundation a annoncé l''arrêt d''El Güegüense, comme de l''ancien Wise Man Maduro, au profit de deux mélanges nouveaux, The Wise Man Corojo et Maduro, faits chez My Father Cigars. Il offrait bois, cuir, une pointe de sucre roux, et une évolution nette entre le premier et le dernier tiers.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 de Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"La racine nord de la maison : cape du Connecticut sur tripe nicaraguayenne. Sombre, terreux, sans amertume — et volontairement placé dans une gamme de prix accessible.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — la ligne corsée, cape broadleaf, chez A.J. Fernández.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — le château de Downton Abbey sur une bague, Connecticut d''Équateur.","vitolas":[],"wrapper":"Connecticut d''Équateur"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — un hommage au Mexique et à ses Olmèques, cape San Andrés, Claro et Maduro.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Ancienne Metapa, rebaptisée en février 2024 pour une question de marque déposée, d''après Foundation, dont le fondateur écrit que le mélange reste le même ; Claro et Maduro, d''après Cigar Coop. Sous-cape Connecticut Broadleaf, tripe d''Estelí et de Jalapa, force annoncée de moyenne à corsée, en Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 et Doble Corona 7 x 54, roulée chez A.J. Fernández d''après Cigar Coop en avril 2024.","vitolas":[],"wrapper":"Sumatra d''Équateur"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Présentée à l''IPCPR 2017 comme déclinaison Maduro d''El Güegüense, avec une cape San Andrés mexicaine ; refaite en 2024 chez My Father Cigars, avec la même cape sur une sous-cape d''Estelí et de Jalapa et une tripe d''Estelí, de Condega et de Jalapa. Force moyenne selon la maison, en Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 et Doble Corona 7 x 54, par vingt.","vitolas":[],"wrapper":"San Andrés (Mexique)"}]',
  `gamme_en` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"The founding blend of 2015, named after a colonial satire passed down orally for centuries, rolled at the time at the TABSA factory, today Aganorsa Leaf. In March 2024, Foundation announced the discontinuation of El Güegüense, as well as of the former Wise Man Maduro, in favour of two new blends, The Wise Man Corojo and Maduro, made at My Father Cigars. It offered wood, leather, a hint of brown sugar, and a clear evolution between the first and the last third.","vitolas":["Corona Gorda","Toro"],"wrapper":"Jalapa Corojo 99"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"The northern root of the house: Connecticut wrapper over Nicaraguan filler. Dark, earthy, without bitterness — and deliberately kept in an affordable price range.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — the full-bodied line, broadleaf wrapper, at A.J. Fernández.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — the castle of Downton Abbey on a band, Ecuadorian Connecticut.","vitolas":[],"wrapper":"Ecuadorian Connecticut"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — a tribute to Mexico and its Olmecs, San Andrés wrapper, Claro and Maduro.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Formerly Metapa, renamed in February 2024 over a trademark issue, according to Foundation, whose founder writes that the blend remains the same; Claro and Maduro, according to Cigar Coop. Connecticut Broadleaf binder, Estelí and Jalapa filler, strength stated as medium to full, in Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 and Doble Corona 7 x 54, rolled at A.J. Fernández according to Cigar Coop in April 2024.","vitolas":[],"wrapper":"Ecuadorian Sumatra"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Presented at IPCPR 2017 as the Maduro variant of El Güegüense, with a Mexican San Andrés wrapper; remade in 2024 at My Father Cigars, with the same wrapper over a binder from Estelí and Jalapa and a filler from Estelí, Condega and Jalapa. Strength medium according to the company, in Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 and Doble Corona 7 x 54, twenty to a box.","vitolas":[],"wrapper":"San Andrés (Mexico)"}]',
  `gamme_es` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"La liga fundacional de 2015, con el nombre de una sátira colonial transmitida oralmente durante siglos, liada entonces en la fábrica TABSA, hoy Aganorsa Leaf. En marzo de 2024, Foundation anunció el cese de El Güegüense, así como del antiguo Wise Man Maduro, en favor de dos mezclas nuevas, The Wise Man Corojo y Maduro, hechas en My Father Cigars. Ofrecía madera, cuero, una pizca de azúcar moreno, y una evolución neta entre el primer y el último tercio.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 de Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"La raíz norte de la casa: capa del Connecticut sobre tripa nicaragüense. Oscuro, terroso, sin amargor — y situado a propósito en una gama de precios accesible.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — la línea fuerte, capa broadleaf, en A.J. Fernández.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — el castillo de Downton Abbey en una anilla, Connecticut de Ecuador.","vitolas":[],"wrapper":"Connecticut de Ecuador"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — un homenaje a México y a sus olmecas, capa San Andrés, Claro y Maduro.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Antigua Metapa, rebautizada en febrero de 2024 por una cuestión de marca registrada, según Foundation, cuyo fundador escribe que la mezcla sigue siendo la misma; Claro y Maduro, según Cigar Coop. Capote Connecticut Broadleaf, tripa de Estelí y de Jalapa, fuerza anunciada de medium a fuerte, en Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 y Doble Corona 7 x 54, enrollada en A.J. Fernández según Cigar Coop en abril de 2024.","vitolas":[],"wrapper":"Sumatra de Ecuador"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Presentada en el IPCPR 2017 como variante Maduro de El Güegüense, con una capa San Andrés mexicana; rehecha en 2024 en My Father Cigars, con la misma capa sobre un capote de Estelí y de Jalapa y una tripa de Estelí, de Condega y de Jalapa. Fuerza medium según la casa, en Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 y Doble Corona 7 x 54, veinte por caja.","vitolas":[],"wrapper":"San Andrés (México)"}]',
  `gamme_de` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"Der Gründungsblend von 2015, benannt nach einer kolonialen Satire, die über Jahrhunderte mündlich überliefert wurde, damals in der Fabrik TABSA gerollt, heute Aganorsa Leaf. Im März 2024 kündigte Foundation die Einstellung von El Güegüense an, ebenso wie die des früheren Wise Man Maduro, zugunsten zweier neuer Blends, The Wise Man Corojo und Maduro, hergestellt bei My Father Cigars. Er bot Holz, Leder, einen Anflug von braunem Zucker und eine klare Entwicklung zwischen erstem und letztem Drittel.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 aus Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"Die nördliche Wurzel des Hauses: Connecticut-Deckblatt über nicaraguanischer Einlage. Dunkel, erdig, ohne Bitterkeit — und bewusst in einer erschwinglichen Preislage gehalten.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — die kräftige Linie, Broadleaf-Deckblatt, bei A.J. Fernández.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — das Schloss von Downton Abbey auf einer Bauchbinde, ecuadorianisches Connecticut.","vitolas":[],"wrapper":"Ecuadorianisches Connecticut"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — eine Hommage an Mexiko und seine Olmeken, San-Andrés-Deckblatt, Claro und Maduro.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Frühere Metapa, im Februar 2024 wegen einer Markenrechtsfrage umbenannt, laut Foundation, deren Gründer schreibt, dass die Mischung dieselbe bleibt; Claro und Maduro, laut Cigar Coop. Umblatt Connecticut Broadleaf, Einlage aus Estelí und Jalapa, angegebene Stärke von medium bis kräftig, in Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 und Doble Corona 7 x 54, laut Cigar Coop im April 2024 bei A.J. Fernández gerollt.","vitolas":[],"wrapper":"Sumatra aus Ecuador"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Auf der IPCPR 2017 als Maduro-Variante von El Güegüense vorgestellt, mit einem mexikanischen Deckblatt San Andrés; 2024 bei My Father Cigars neu gefertigt, mit demselben Deckblatt über einem Umblatt aus Estelí und Jalapa und einer Einlage aus Estelí, Condega und Jalapa. Stärke medium laut Haus, in Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 und Doble Corona 7 x 54, zu je zwanzig in der Schachtel.","vitolas":[],"wrapper":"San Andrés (Mexiko)"}]',
  `gamme_zh` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"2015年的奠基配方，得名于一出口传数百年的殖民时期讽刺剧，当时在 TABSA 工厂卷制，该厂如今是 Aganorsa Leaf。2024年3月，Foundation 宣布停产 El Güegüense，连同此前的 Wise Man Maduro，改以两款新配方 The Wise Man Corojo 与 Maduro 取代，由 My Father Cigars 制作。它有木质、皮革，一丝红糖，从首段到末段有清晰的推进。","vitolas":["Corona Gorda","Toro"],"wrapper":"哈拉帕可乐多99"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"这家的北方之根：康涅狄格茄衣配尼加拉瓜茄芯。深色、带土味、不苦——并有意保持在可及的价位。","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016年——浓烈的一线，broadleaf 茄衣，在 A.J. Fernández 制作。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017年——茄标上的唐顿庄园城堡，厄瓜多尔康涅狄格茄衣。","vitolas":[],"wrapper":"厄瓜多尔康涅狄格"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"2022年 PCA——向墨西哥及其奥尔梅克人致敬，圣安德烈斯茄衣，Claro 与 Maduro。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"前身为Metapa，2024年二月因商标问题更名，据Foundation所述，其创始人写道，拼配保持不变；据Cigar Coop，为Claro和Maduro。茄套为Connecticut Broadleaf，茄芯来自Estelí和Jalapa，标称烟力为medium至浓郁，规格为Robusto 5 x 50、Corona Gorda 5½ x 48、Toro 6 x 52和Doble Corona 7 x 54，据Cigar Coop于2024年四月所述，在A.J. Fernández卷制。","vitolas":[],"wrapper":"厄瓜多尔Sumatra"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"在IPCPR 2017上作为El Güegüense的Maduro版本亮相，采用墨西哥San Andrés茄衣；2024年在My Father Cigars重新制作，茄衣相同，茄套取自Estelí和Jalapa，茄芯取自Estelí、Condega和Jalapa。据该公司，烟力为medium，规格为Corona 5 x 48、Robusto 5½ x 50、Toro 6 x 52和Doble Corona 7 x 54，每盒二十支。","vitolas":[],"wrapper":"San Andrés（墨西哥）"}]',
  `gamme_ar` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"الخلطة التأسيسية لعام 2015، التي تحمل اسم هجائية استعمارية تناقلتها الأفواه قروناً، وكانت تُلفّ حينذاك في مصنع TABSA، وهو اليوم Aganorsa Leaf. وفي آذار/مارس 2024 أعلنت Foundation وقف إنتاج El Güegüense، وكذلك وقف إنتاج Wise Man Maduro السابق، لصالح خلطتين جديدتين، The Wise Man Corojo وMaduro، تُصنعان لدى My Father Cigars. وكانت تقدّم خشبًا وجلدًا ولمسة سكر بنّي، مع تطوّر واضح بين الثلث الأول والأخير.","vitolas":["Corona Gorda","Toro"],"wrapper":"كوروخو 99 من خالابا"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"الجذر الشمالي للدار: غلاف كونيتيكت على حشوة نيكاراغوية. داكن، ترابي، بلا مرارة — وموضوع عمداً في نطاق سعري في المتناول.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — الخطّ القويّ، غلاف برودليف، لدى A.J. Fernández.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — قصر داونتون آبي على حزام، كونيتيكت إكوادوري.","vitolas":[],"wrapper":"كونيتيكت إكوادوري"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — تحيّة للمكسيك وأولميكها، غلاف سان أندريس، Claro وMaduro.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"كان سابقًا Metapa، وأُعيدت تسميته في فبراير 2024 لمسألة تتعلق بالعلامة التجارية المسجّلة، بحسب Foundation التي يكتب مؤسسها أن التوليفة تبقى نفسها؛ Claro وMaduro، بحسب Cigar Coop. رابط Connecticut Broadleaf، وحشوة من Estelí وJalapa، وقوة معلنة بين medium وقوية، بمقاسات Robusto 5 x 50 وCorona Gorda 5½ x 48 وToro 6 x 52 وDoble Corona 7 x 54، يُلَفّ لدى A.J. Fernández بحسب Cigar Coop في أبريل 2024.","vitolas":[],"wrapper":"Sumatra من الإكوادور"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"قُدّم في IPCPR 2017 بوصفه النسخة Maduro من El Güegüense، بغلاف خارجي San Andrés مكسيكي؛ وأُعيد صنعه في 2024 لدى My Father Cigars، بالغلاف نفسه فوق رابط من Estelí وJalapa وحشوة من Estelí وCondega وJalapa. قوة medium بحسب الشركة، بمقاسات Corona 5 x 48 وRobusto 5½ x 50 وToro 6 x 52 وDoble Corona 7 x 54، بواقع عشرين في العلبة.","vitolas":[],"wrapper":"San Andrés (المكسيك)"}]',
  `source` = IF(LOCATE(CAST(' ; lot 5 bis : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 bis : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Foundation Cigar Company';

