-- ── General Cigar ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"La gamme la plus vendue de la maison aux États-Unis. Cape Connecticut Shade, douce et crémeuse, sur assemblage dominicain et jamaïcain. Notes de crème, cèdre léger, noisette. Format Café Baron de Rothschild (42 x 127mm). Le cigare des terrasses ensoleillées et des après-midi sans urgence.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Série inspirée des moteurs Harley-Davidson V-twin, aux formats nommés d''après des pièces : V660 Carb, V554 Piston, V770 Engine. Cape d''Équateur sur nicaraguayen et hondurien. Corsée, notes de cuir, café noir, chocolat. Cigare de route et d''Amérique profonde.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Équateur"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"Le portefeuille de la famille Toraño, racheté en septembre 2014 — les marques seulement ; la société Toraño Family Cigar a cessé, et Charlie Toraño est resté consultant. Carlos Toraño est mort en février 2022.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Marque de bundles à petit prix présentée par General Cigar à l''IPCPR 2016, d''origine Nicaragua, avec un Habano (cape habano nicaraguayenne) et un Connecticut (cape Connecticut Shade du Honduras) ; six déclinaisons en 2025, dont Full (septembre 2021), roulée à la main à STG Estelí. Depuis le 1er août 2025, STG la confie à l''équipe de vente de Forged Cigar Company, sans changement de produit.","vitolas":[],"wrapper":"Non divulguée"}]',
  `gamme_en` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"America''s best-seller for 30 years. Connecticut Shade wrapper, soft and creamy, over Dominican-Jamaican blend. Notes of cream, light cedar, hazelnut. The cigar of sunny terraces and unhurried afternoons. Consistent, accessible, never disappointing.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Series inspired by Harley-Davidson V-twin engines. Format names: V660 Carb, V554 Piston, V770 Engine. Ecuadorian wrapper over Nicaraguan-Honduran. Full body, notes of motorcycle leather, black coffee, chocolate, engine oil (really). A cigar of the open road, freedom, deep America.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuadorian"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"The Toraño family''s portfolio, bought in September 2014 — the brands only; the Toraño Family Cigar company ceased, and Charlie Toraño stayed on as a consultant. Carlos Toraño died in February 2022.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Brand of low-priced bundles presented by General Cigar at IPCPR 2016, of Nicaraguan origin, with a Habano (Nicaraguan habano wrapper) and a Connecticut (Honduran Connecticut Shade wrapper); six variants in 2025, including Full (September 2021), hand-rolled at STG Estelí. Since 1 August 2025, STG has entrusted it to the sales team of Forged Cigar Company, with no change to the product.","vitolas":[],"wrapper":"Undisclosed"}]',
  `gamme_es` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"El superventas estadounidense desde hace treinta años. Capa Connecticut Shade suave y cremosa sobre liga dominicano-jamaicana. Crema, cedro ligero, avellana. Formato Café Baron de Rothschild (42 x 127mm). El puro de las terrazas soleadas y de las tardes sin prisa. Regular, accesible, nunca decepciona.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Serie inspirada en los motores V-twin de Harley-Davidson, con formatos bautizados como piezas: V660 Carb, V554 Piston, V770 Engine. Capa de Ecuador sobre tripa nicaragüense y hondureña. Potente, con notas de cuero, café negro y chocolate. Un puro de carretera y de la América profunda.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"El portafolio de la familia Toraño, comprado en septiembre de 2014 — solo las marcas; la sociedad Toraño Family Cigar cesó, y Charlie Toraño quedó como consultor. Carlos Toraño murió en febrero de 2022.","vitolas":[],"wrapper":"No divulgada"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Marca de bundles de precio bajo presentada por General Cigar en el IPCPR 2016, de origen Nicaragua, con un Habano (capa habano nicaragüense) y un Connecticut (capa Connecticut Shade de Honduras); seis variantes en 2025, entre ellas Full (septiembre de 2021), enrollada a mano en STG Estelí. Desde el 1 de agosto de 2025, STG la confía al equipo de ventas de Forged Cigar Company, sin cambio de producto.","vitolas":[],"wrapper":"No divulgada"}]',
  `gamme_de` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"Der amerikanische Bestseller seit dreißig Jahren. Mildes, cremiges Connecticut-Shade-Deckblatt über dominikanisch-jamaikanischer Mischung. Sahne, leichte Zeder, Haselnuss. Format Café Baron de Rothschild (42 x 127 mm). Die Zigarre für sonnige Terrassen und Nachmittage ohne Eile. Gleichmäßig, zugänglich, nie enttäuschend.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Eine Serie, inspiriert von den V-Twin-Motoren von Harley-Davidson, mit Formaten, die wie Bauteile heißen: V660 Carb, V554 Piston, V770 Engine. Deckblatt aus Ecuador über nicaraguanischer und honduranischer Einlage. Kräftig, mit Noten von Leder, schwarzem Kaffee und Schokolade. Eine Zigarre der Landstraße und des tiefen Amerika.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"Das Portfolio der Familie Toraño, im September 2014 gekauft — nur die Marken; die Gesellschaft Toraño Family Cigar hörte auf, und Charlie Toraño blieb Berater. Carlos Toraño starb im Februar 2022.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Marke von bundles zu niedrigem Preis, von General Cigar auf der IPCPR 2016 vorgestellt, Herkunft Nicaragua, mit einem Habano (nicaraguanisches Habano-Deckblatt) und einem Connecticut (Deckblatt Connecticut Shade aus Honduras); sechs Varianten im Jahr 2025, darunter Full (September 2021), von Hand gerollt bei STG Estelí. Seit dem 1. August 2025 vertraut STG sie dem Vertriebsteam von Forged Cigar Company an, ohne Änderung am Produkt.","vitolas":[],"wrapper":"Nicht angegeben"}]',
  `gamme_zh` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"三十年来的美国畅销之作。柔和奶油般的康涅狄格阴植茄衣，内裹多米尼加与牙买加配方。奶油、轻盈雪松、榛子。Café Baron de Rothschild 规格（42 x 127 毫米）。这是阳光露台与不赶时间的午后的雪茄。稳定、平易，从不让人失望。","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"这一系列取材于哈雷戴维森的 V-twin 发动机，各规格以零件命名：V660 Carb、V554 Piston、V770 Engine。厄瓜多尔茄衣，包裹尼加拉瓜与洪都拉斯茄芯。风格厚重，带皮革、黑咖啡与巧克力的气息——属于公路与美国腹地的一支雪茄。","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"厄瓜多尔"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"托拉尼奥家族的品牌组合，2014年9月买下——只有品牌；Toraño Family Cigar 公司停业，查理·托拉尼奥留任顾问。卡洛斯·托拉尼奥2022年2月去世。","vitolas":[],"wrapper":"未公开"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"低价位bundles品牌，由General Cigar在IPCPR 2016上亮相，原产国为尼加拉瓜，包含Habano版（尼加拉瓜habano茄衣）与Connecticut版（洪都拉斯Connecticut Shade茄衣）；2025年共有六个版本，其中包括Full（2021年九月），在STG Estelí手工卷制。自2025年八月1日起，STG将其交由Forged Cigar Company的销售团队负责，产品不变。","vitolas":[],"wrapper":"未公开"}]',
  `gamme_ar` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"الأكثر مبيعًا في أمريكا منذ ثلاثين عامًا. غلاف كونيتيكت شيد لطيف وقشديّ فوق خلطة دومينيكية-جامايكية. قشدة، أرز خفيف، بندق. قياس كافيه بارون دي روتشيلد (42 × 127 مم). سيجار الشرفات المشمسة والأصائل بلا عجلة. منتظم، سهل المنال، لا يخيّب.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"سلسلة مستوحاة من محرّكات هارلي ديفيدسون ثنائية الأسطوانة، بقياسات تحمل أسماء قطع المحرّك: V660 Carb وV554 Piston وV770 Engine. غلافة من الإكوادور فوق حشوة نيكاراغوية وهندوراسية. قوية، بنكهات الجلد والقهوة السوداء والشوكولاتة — سيجارة الطريق وأمريكا العميقة.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"إكوادوري"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"محفظة عائلة تورانيو، اشتُريت في أيلول/سبتمبر 2014 — العلامات فقط؛ توقّفت شركة Toraño Family Cigar، وبقي تشارلي تورانيو مستشارًا. وتوفّي كارلوس تورانيو في شباط/فبراير 2022.","vitolas":[],"wrapper":"غير معلن"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"علامة bundles منخفضة السعر قدّمتها General Cigar في IPCPR 2016، بلد المنشأ نيكاراغوا، تضم Habano (غلاف خارجي habano نيكاراغوي) وConnecticut (غلاف خارجي Connecticut Shade من هندوراس)؛ ست نسخ في 2025، منها Full (سبتمبر 2021)، تُلَفّ يدويًا في STG Estelí. ومنذ 1 أغسطس 2025 تُسندها STG إلى فريق المبيعات في Forged Cigar Company، دون تغيير في المنتج.","vitolas":[],"wrapper":"غير معلن"}]',
  `source` = IF(LOCATE(CAST(' ; requalification : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; requalification : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'General Cigar';

-- ── Golden Djawa ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('que leurs fiches disent désormais. Golden Djawa et BIN sont les deux premières maisons de la ville à entrer ici sous leur propre nom.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'que leurs fiches disent désormais. Golden Djawa et BIN sont les deux premières maisons de la ville à entrer ici sous leur propre nom.', 'que leurs fiches disent. Golden Djawa et BIN sont les deux maisons de la ville qui ont leur fiche sous leur propre nom.'), `history`),
  `history_en` = IF(LOCATE(CAST('now say. Golden Djawa and BIN are the first two houses of the town to enter here under their own names.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'now say. Golden Djawa and BIN are the first two houses of the town to enter here under their own names.', 'say. Golden Djawa and BIN are the two houses of the town that have an entry under their own names.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('dicen desde ahora. Golden Djawa y BIN son las dos primeras casas de la ciudad en entrar aquí con su propio nombre.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'dicen desde ahora. Golden Djawa y BIN son las dos primeras casas de la ciudad en entrar aquí con su propio nombre.', 'dicen. Golden Djawa y BIN son las dos casas de la ciudad que tienen ficha con su propio nombre.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('nun nennen. Golden Djawa und BIN sind die ersten beiden Häuser der Stadt, die hier unter eigenem Namen eintreten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'nun nennen. Golden Djawa und BIN sind die ersten beiden Häuser der Stadt, die hier unter eigenem Namen eintreten.', 'nennen. Golden Djawa und BIN sind die beiden Häuser der Stadt, die unter eigenem Namen einen Eintrag haben.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('如今已写明。Golden Djawa 和 BIN 是这座城市头两家以自己名字进入本图集的公司。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '如今已写明。Golden Djawa 和 BIN 是这座城市头两家以自己名字进入本图集的公司。', '已写明。Golden Djawa 和 BIN 是这座城市以自己名字拥有词条的两家公司。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('بطاقاتهما الآن. وغولدن جاوا وBIN أوّل دارين من المدينة تدخلان هنا باسميهما.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'بطاقاتهما الآن. وغولدن جاوا وBIN أوّل دارين من المدينة تدخلان هنا باسميهما.', 'بطاقاتهما. وGolden Djawa وBIN هما الدارتان من المدينة اللتان لهما بطاقة باسميهما.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Golden Djawa';

-- ── HVC Cigars ──
UPDATE `brands` SET
  `source` = IF(LOCATE(CAST(' ; lot 5 bis : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 bis : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'HVC Cigars';

-- ── Hoyo de Monterrey ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(' ; l''atlas l''écrivait chez El Rey del Mundo, une fabrique qui n''existe plus sous ce nom, et se corrige' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, ' ; l''atlas l''écrivait chez El Rey del Mundo, une fabrique qui n''existe plus sous ce nom, et se corrige', ''), `history`),
  `history_en` = IF(LOCATE(CAST('; this atlas had it at El Rey del Mundo, a factory that no longer exists under that name, and corrects itself' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, '; this atlas had it at El Rey del Mundo, a factory that no longer exists under that name, and corrects itself', ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('; el atlas la ponía en El Rey del Mundo, una fábrica que ya no existe con ese nombre, y se corrige' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '; el atlas la ponía en El Rey del Mundo, una fábrica que ya no existe con ese nombre, y se corrige', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('; dieser Atlas hatte sie bei El Rey del Mundo, einer Fabrik, die unter diesem Namen nicht mehr besteht, und korrigiert sich' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, '; dieser Atlas hatte sie bei El Rey del Mundo, einer Fabrik, die unter diesem Namen nicht mehr besteht, und korrigiert sich', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('；本图集原先写在 El Rey del Mundo，那家厂已不再以此名存在，予以更正' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '；本图集原先写在 El Rey del Mundo，那家厂已不再以此名存在，予以更正', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('؛ وكان هذا الأطلس يضعها عند El Rey del Mundo، وهو مصنع لم يعد قائمًا بهذا الاسم، ويصحّح نفسه' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '؛ وكان هذا الأطلس يضعها عند El Rey del Mundo، وهو مصنع لم يعد قائمًا بهذا الاسم، ويصحّح نفسه', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Hoyo de Monterrey';

-- ── IGM Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Elle entre parce que l''atlas nommait déjà IGM comme fabrique de Casdagli sans lui donner de fiche — la même logique' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Elle entre parce que l''atlas nommait déjà IGM comme fabrique de Casdagli sans lui donner de fiche — la même logique', 'Elle a sa fiche parce qu''IGM est la fabrique de Casdagli — la même logique'), `history`),
  `history_en` = IF(LOCATE(CAST('It enters because the atlas already named IGM as Casdagli''s factory without giving it an entry — the same logic' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'It enters because the atlas already named IGM as Casdagli''s factory without giving it an entry — the same logic', 'It has an entry because IGM is Casdagli''s factory — the same logic'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Entra porque el atlas ya nombraba a IGM como fábrica de Casdagli sin darle ficha — la misma lógica' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Entra porque el atlas ya nombraba a IGM como fábrica de Casdagli sin darle ficha — la misma lógica', 'Tiene ficha porque IGM es la fábrica de Casdagli — la misma lógica'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Sie tritt ein, weil der Atlas IGM bereits als Fabrik von Casdagli nannte, ohne ihr einen Eintrag zu geben — dieselbe Logik' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Sie tritt ein, weil der Atlas IGM bereits als Fabrik von Casdagli nannte, ohne ihr einen Eintrag zu geben — dieselbe Logik', 'Sie hat einen Eintrag, weil IGM die Fabrik von Casdagli ist — dieselbe Logik'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它之所以进入图集，是因为图集早已把 IGM 列为 Casdagli 的工厂却没有给它词条——与' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它之所以进入图集，是因为图集早已把 IGM 列为 Casdagli 的工厂却没有给它词条——与', '它有词条，是因为 IGM 是 Casdagli 的工厂——与'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وتدخل لأنّ الأطلس كان يسمّي IGM مصنعَ Casdagli من دون أن يعطيها بطاقة' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وتدخل لأنّ الأطلس كان يسمّي IGM مصنعَ Casdagli من دون أن يعطيها بطاقة', 'ولها بطاقة لأنّ IGM مصنع Casdagli'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'IGM Cigars';

