 WHERE `name` = 'Illusione';

-- ── J. Fuego ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('est une fabrique d''Estelí que l''atlas nommait sans la connaître : la fiche 7-20-4' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'est une fabrique d''Estelí que l''atlas nommait sans la connaître : la fiche 7-20-4', 'est une fabrique d''Estelí : la fiche 7-20-4'), `history`),
  `history_en` = IF(LOCATE(CAST('Estelí that this atlas named without knowing it:' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Estelí that this atlas named without knowing it:', 'Estelí:'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Estelí que este atlas nombraba sin conocerla:' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Estelí que este atlas nombraba sin conocerla:', 'Estelí:'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Estelí, die dieser Atlas nannte, ohne sie zu kennen:' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Estelí, die dieser Atlas nannte, ohne sie zu kennen:', 'Estelí:'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('工厂，本图集曾提及却不了解：' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '工厂，本图集曾提及却不了解：', '工厂：'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('إستيلي ذكره هذا الأطلس دون أن يعرفه:' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'إستيلي ذكره هذا الأطلس دون أن يعرفه:', 'إستيلي:'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'J. Fuego';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Un mot sur 777 : le premier recensement de cet atlas la cherchait comme une maison hondurienne et n''avait rien trouvé. C''était une marque de J. Fuego. Le nom manquant n''était pas absent — il était rangé sous le mauvais pays.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Un mot sur 777 : le premier recensement de cet atlas la cherchait comme une maison hondurienne et n''avait rien trouvé. C''était une marque de J. Fuego. Le nom manquant n''était pas absent — il était rangé sous le mauvais pays.', 'Un mot sur 777 : c''est une marque de J. Fuego, non une maison hondurienne à part.'), `history`),
  `history_en` = IF(LOCATE(CAST('this atlas''s first census looked for it as a Honduran house and found nothing. It was a J. Fuego brand. The missing name was not absent — it was filed under the wrong country.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'this atlas''s first census looked for it as a Honduran house and found nothing. It was a J. Fuego brand. The missing name was not absent — it was filed under the wrong country.', 'it is a J. Fuego brand, not a separate Honduran house.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('el primer censo de este atlas la buscaba como casa hondureña y no había encontrado nada. Era una marca de J. Fuego. El nombre que faltaba no estaba ausente — estaba archivado bajo el país equivocado.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'el primer censo de este atlas la buscaba como casa hondureña y no había encontrado nada. Era una marca de J. Fuego. El nombre que faltaba no estaba ausente — estaba archivado bajo el país equivocado.', 'es una marca de J. Fuego, no una casa hondureña aparte.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die erste Bestandsaufnahme dieses Atlas suchte sie als honduranisches Haus und fand nichts. Es war eine Marke von J. Fuego. Der fehlende Name fehlte nicht — er war unter dem falschen Land abgelegt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die erste Bestandsaufnahme dieses Atlas suchte sie als honduranisches Haus und fand nichts. Es war eine Marke von J. Fuego. Der fehlende Name fehlte nicht — er war unter dem falschen Land abgelegt.', 'Es ist eine Marke von J. Fuego, kein eigenständiges honduranisches Haus.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集首次普查曾把它当作一家洪都拉斯老号来找，一无所获。它其实是 J. Fuego 的一个牌子。缺失的名字并非不存在——只是被归在了错误的国家之下。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集首次普查曾把它当作一家洪都拉斯老号来找，一无所获。它其实是 J. Fuego 的一个牌子。缺失的名字并非不存在——只是被归在了错误的国家之下。', '它是 J. Fuego 的一个牌子，并非一家独立的洪都拉斯公司。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('بحث عنها الإحصاء الأوّل لهذا الأطلس بوصفها دارًا هندوراسية فلم يجد شيئًا. كانت علامةً لجي. فويغو. الاسم الناقص لم يكن غائبًا — بل كان مصنَّفًا تحت البلد الخطأ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'بحث عنها الإحصاء الأوّل لهذا الأطلس بوصفها دارًا هندوراسية فلم يجد شيئًا. كانت علامةً لجي. فويغو. الاسم الناقص لم يكن غائبًا — بل كان مصنَّفًا تحت البلد الخطأ.', 'هي علامة لجي. فويغو، وليست دارًا هندوراسية مستقلّة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'J. Fuego';

