  `gamme_es` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","story":"La serie que lleva el año de fundación, y la capa de Camerún que es la firma de la casa: madera especiada, avellana tostada, cuero claro. Un figurado, forma que La Aurora lía desde hace mucho.","vitolas":["Figurado"],"wrapper":"Camerún"},{"name":"107","color":"#A0522D","force":"Medium","story":"Una serie de aniversario convertida en permanente. Más contemporánea que la 1903, más redonda, y pensada para quienes descubren la casa.","vitolas":["Robusto"],"wrapper":"Habano de Ecuador"},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","story":"El nombre del fundador, Eduardo León Jimenes, en una línea de la casa.","vitolas":[],"wrapper":"Connecticut de Ecuador"}]',
  `gamme_de` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","story":"Die Serie, die das Gründungsjahr trägt, und das Kamerun-Deckblatt, das die Handschrift des Hauses ist: würziges Holz, geröstete Haselnuss, helles Leder. Ein Figurado — eine Form, die La Aurora seit Langem rollt.","vitolas":["Figurado"],"wrapper":"Kamerun"},{"name":"107","color":"#A0522D","force":"Medium","story":"Eine Jubiläumsserie, die dauerhaft wurde. Zeitgenössischer als die 1903, runder, und für jene gedacht, die das Haus entdecken.","vitolas":["Robusto"],"wrapper":"Habano aus Ecuador"},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","story":"Der Name des Gründers, Eduardo León Jimenes, auf einer Linie des Hauses.","vitolas":[],"wrapper":"Ecuadorianisches Connecticut"}]',
  `gamme_zh` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","story":"以创立年份命名的系列，配上作为这家签名的喀麦隆茄衣：香料木质、烤榛子、浅色皮革。一支异形茄——这是极光长久以来卷制的形制。","vitolas":["Figurado"],"wrapper":"喀麦隆"},{"name":"107","color":"#A0522D","force":"Medium","story":"一个由纪念系列转为常规的产品。比1903更当代、更圆润，是为初识这家的人而设。","vitolas":["Robusto"],"wrapper":"厄瓜多尔哈瓦那种"},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","story":"创始人爱德华多·莱昂·希梅内斯的名字，用于公司的一条线。","vitolas":[],"wrapper":"厄瓜多尔康涅狄格"}]',
  `gamme_ar` = '[{"name":"1903 Preferidos","color":"#8B4513","force":"Medium","story":"السلسلة التي تحمل سنة التأسيس، والغلاف الكاميروني الذي هو توقيع الدار: خشب متبَّل وبندق محمّص وجلد فاتح. «فيغورادو»، وهو شكل تلفّه «لا أورورا» منذ زمن بعيد.","vitolas":["Figurado"],"wrapper":"كاميرون"},{"name":"107","color":"#A0522D","force":"Medium","story":"سلسلة تذكارية صارت دائمة. أكثر معاصرة من «1903» وأكثر استدارة، ومصمَّمة لمن يكتشف الدار حديثاً.","vitolas":["Robusto"],"wrapper":"هابانو إكوادوري"},{"name":"León Jimenes","color":"#8B5A2B","force":"Mild-Medium","story":"اسم المؤسّس، إدواردو ليون خيمينيس، على خطّ من خطوط الدار.","vitolas":[],"wrapper":"كونيتيكت إكوادوري"}]',
