-- ── Rocky Patel ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Le nom renvoie à l''origine des capes du premier assemblage, récoltées en 1992 — pas à l''âge du tabac vendu aujourd''hui. Cape Ecuador Connecticut sur tabacs honduriens et nicaraguayens. Notes de noisette grillée, caramel, bois clair. Mi-corsée à corsée, équilibrée ; la série Vintage reste l''une des propositions les plus narratives du marché : chaque millésime raconte une récolte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lancée pour les 50 ans de Rocky Patel — l''homme, pas la marque. Assemblage hondurien-nicaraguayen complexe, cape d''Équateur cultivée en plein soleil. Notes de café, épices orientales, sous-bois. Format Toro, 50 x 152mm. Une gamme qui reste dans l''ombre des séries Vintage alors qu''elle en dit autant sur la maison.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Plein soleil d''Équateur"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gamme accessible de la maison. Formats Robusto et Toro, cape Connecticut, tabacs hondurien et nicaraguayen. Notes douces de crème et de noisette. Le premier Rocky Patel pour un néophyte — facile d''approche, régulier, gratifiant. Prix démocratique.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Les cigares d''Hamlet Paredes, ancien rouleur de Partagás et ambassadeur d''Habanos, engagé en 2015 — Tabaquero d''abord, puis Liberation et 25th Year. Paredes est parti en août 2022 ; la maison garde le nom et les lignes, et a arrêté Tabaquero.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"La première marque de Rocky Patel, dans les années 1990, avant que la maison ne prenne son nom.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"Lancée en 2013 par Nish Patel, frère de Rocky Patel et vice-président exécutif de la maison, à la suite de sa première sortie de 2011 ; en mars 2024, un article de la Premium Cigar Association le dit à la tête de la ligne, produite au Nicaragua. Tabacs de San Andrés et des fermes nicaraguayennes de la maison sous la cape, en Robusto (5 ½ x 50), Toro (6 x 52), Torpedo (6 ⅛ x 52) et Sixty (6 x 60), dit rockypatel.com.","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]',
  `gamme_en` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"The name refers to the origin of the wrappers used in the first blend, harvested in 1992 — not to the age of the tobacco sold today. Ecuador Connecticut wrapper over Honduran and Nicaraguan leaf. Toasted hazelnut, caramel, pale wood. A balanced medium-full, and the Vintage series remains one of the most narrative propositions on the market: each vintage tells of a harvest.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Launched for Rocky Patel''s fiftieth birthday — the man, not the brand. A complex Honduran-Nicaraguan blend, Ecuadorian wrapper grown in full sun. Coffee, oriental spice, forest floor. Toro format, 50 x 152mm. A range that stays in the shadow of the Vintage series though it says just as much about the house.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"The house''s accessible range. Robusto and Toro formats, Connecticut wrapper, Honduran and Nicaraguan leaf. Gentle cream and hazelnut. The first Rocky Patel for a newcomer — easy to approach, consistent, rewarding. A democratic price.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"The cigars of Hamlet Paredes, former Partagás roller and Habanos ambassador, hired in 2015 — Tabaquero first, then Liberation and 25th Year. Paredes left in August 2022; the house keeps the name and the lines, and discontinued Tabaquero.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"Rocky Patel''s first brand, in the 1990s, before the house took his name.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"Launched in 2013 by Nish Patel, brother of Rocky Patel and executive vice president of the company, following his first release in 2011; in March 2024, an article by the Premium Cigar Association says he heads the line, which is produced in Nicaragua. Tobaccos from San Andrés and from the company''s Nicaraguan farms under the wrapper, in Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) and Sixty (6 x 60), according to rockypatel.com.","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]',
  `gamme_es` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"El nombre remite al origen de las capas del primer ligado, cosechadas en 1992, no a la edad del tabaco que se vende hoy. Capa Ecuador Connecticut sobre tabacos hondureños y nicaragüenses. Avellana tostada, caramelo, madera clara. Un medio-fuerte equilibrado, y la serie Vintage sigue siendo una de las propuestas más narrativas del mercado: cada añada cuenta una cosecha.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lanzada por los 50 años de Rocky Patel, el hombre, no la marca. Ligado hondureño-nicaragüense complejo, capa ecuatoriana cultivada a pleno sol. Café, especias orientales, sotobosque. Formato Toro, 50 x 152mm. Una gama que permanece a la sombra de las series Vintage aunque diga otro tanto sobre la casa.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"De sol de Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gama accesible de la casa. Formatos Robusto y Toro, capa Connecticut, tabacos hondureño y nicaragüense. Notas suaves de crema y avellana. El primer Rocky Patel para un neófito: fácil de abordar, regular, gratificante. Precio democrático.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Los puros de Hamlet Paredes, antiguo torcedor de Partagás y embajador de Habanos, contratado en 2015 — Tabaquero primero, luego Liberation y 25th Year. Paredes se fue en agosto de 2022; la casa conserva el nombre y las líneas, y retiró Tabaquero.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"La primera marca de Rocky Patel, en los años 1990, antes de que la casa tomara su nombre.","vitolas":[],"wrapper":"No divulgada"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"Lanzada en 2013 por Nish Patel, hermano de Rocky Patel y vicepresidente ejecutivo de la casa, a raíz de su primer lanzamiento de 2011; en marzo de 2024, un artículo de la Premium Cigar Association afirma que está al frente de la línea, producida en Nicaragua. Tabacos de San Andrés y de las fincas nicaragüenses de la casa bajo la capa, en Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) y Sixty (6 x 60), según rockypatel.com.","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]',
  `gamme_de` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Der Name verweist auf die Herkunft der Deckblätter der ersten Mischung, geerntet 1992 — nicht auf das Alter des heute verkauften Tabaks. Deckblatt Ecuador Connecticut über honduranischem und nicaraguanischem Tabak. Geröstete Haselnuss, Karamell, helles Holz. Ein ausgewogenes Medium-Full, und die Vintage-Serie bleibt eines der erzählerischsten Angebote des Marktes: Jeder Jahrgang erzählt von einer Ernte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Zum 50. Geburtstag von Rocky Patel lanciert — dem Mann, nicht der Marke. Komplexe honduranisch-nicaraguanische Mischung, ecuadorianisches Deckblatt aus vollem Sonnenanbau. Kaffee, orientalische Gewürze, Waldboden. Format Toro, 50 x 152 mm. Eine Serie, die im Schatten der Vintage-Reihen bleibt, obwohl sie ebenso viel über das Haus erzählt.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"Die zugängliche Serie des Hauses. Formate Robusto und Toro, Deckblatt Connecticut, honduranischer und nicaraguanischer Tabak. Milde Noten von Sahne und Haselnuss. Der erste Rocky Patel für Einsteiger — leicht zugänglich, gleichmäßig, dankbar. Ein demokratischer Preis.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Die Zigarren von Hamlet Paredes, ehemaligem Partagás-Roller und Habanos-Botschafter, 2015 engagiert — zuerst Tabaquero, dann Liberation und 25th Year. Paredes ging im August 2022; das Haus behält Namen und Linien und stellte Tabaquero ein.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"Rocky Patels erste Marke, in den 1990ern, bevor das Haus seinen Namen annahm.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"2013 von Nish Patel, dem Bruder von Rocky Patel und Executive Vice President des Hauses, im Anschluss an seine erste Veröffentlichung von 2011 auf den Markt gebracht; im März 2024 nennt ihn ein Artikel der Premium Cigar Association an der Spitze der Linie, die in Nicaragua produziert wird. Tabake aus San Andrés und von den nicaraguanischen Farmen des Hauses unter dem Deckblatt, in Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) und Sixty (6 x 60), laut rockypatel.com.","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]',
  `gamme_zh` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"名字指的是首款配方所用茄衣的来历——那批茄衣收于 1992 年，而不是今天所售烟叶的年份。厄瓜多尔康涅狄格茄衣，包裹洪都拉斯与尼加拉瓜烟叶。烤榛子、焦糖、浅色木。中偏浓而均衡；Vintage 系列至今仍是市场上最有叙事性的构想之一：每一个年份都在讲一次收成。","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"为洛基·帕特尔五十岁而推出——是这个人，不是这个牌子。复杂的洪都拉斯－尼加拉瓜配方，茄衣来自厄瓜多尔的全日照种植。咖啡、东方香料、林下腐叶。Toro 规格，50 x 152 毫米。这个系列一直被 Vintage 各系列的光芒盖住，可它讲出的老号故事并不更少。","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"厄瓜多尔日光种植"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"这家老号的入门系列。Robusto 与 Toro 两种规格，康涅狄格茄衣，洪都拉斯与尼加拉瓜烟叶。奶油与榛子的柔和气息。给新手的第一支洛基·帕特尔——好上手、稳定、有回报。价格亲民。","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"哈姆雷特·帕雷德斯的雪茄——他曾是 Partagás 的卷工与 Habanos 的大使，2015年受聘——先是 Tabaquero，再是 Liberation 与 25th Year。帕雷德斯2022年8月离开；公司保留名字与各线，停掉了 Tabaquero。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"洛基·帕特尔的首个品牌，1990年代，早于公司改用他的名字。","vitolas":[],"wrapper":"未公开"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"2013年由Nish Patel推出，他是Rocky Patel的兄弟、公司的执行副总裁，此前于2011年首次发售；2024年三月，Premium Cigar Association的一篇文章称他主持该产品线，该产品线在尼加拉瓜生产。茄衣之下为来自San Andrés和公司尼加拉瓜农场的烟叶，规格为Robusto（5½ x 50）、Toro（6 x 52）、Torpedo（6⅛ x 52）和Sixty（6 x 60），据rockypatel.com。","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]',
  `gamme_ar` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"يشير الاسم إلى أصل أغلفة الخلطة الأولى، وقد جُنيت عام 1992 — لا إلى عمر التبغ المُباع اليوم. غلاف إكوادور كونيتيكت فوق تبغ هندوراسي ونيكاراغوي. بندق محمّص، كراميل، خشب فاتح. قوّة متوسطة-عالية متوازنة، وتبقى سلسلة Vintage من أكثر الطروحات سرديّة في السوق: كل سنة تروي حصادًا.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"أُطلقت في عيد ميلاد روكي باتيل الخمسين — الرجل لا العلامة. خلطة هندوراسية-نيكاراغوية معقّدة، وغلاف إكوادوري مزروع في الشمس الكاملة. قهوة، توابل شرقية، أرض غابة. قياس تورو، 50 × 152 مم. مجموعة تبقى في ظلّ سلاسل Vintage، مع أنها تقول عن الدار قدر ما تقوله تلك.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"المجموعة السهلة لدى الدار. قياسا روبوستو وتورو، غلاف كونيتيكت، وتبغ هندوراسي ونيكاراغوي. نفحات ناعمة من القشدة والبندق. أول روكي باتيل للمبتدئ — سهل التناول، ثابت، مُجزٍ. وسعره في متناول الجميع.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"سيجارات هاملت باريديس، لفّاف Partagás السابق وسفير Habanos، الذي استُقدم سنة 2015 — Tabaquero أوّلًا، ثم Liberation و25th Year. غادر باريديس في آب/أغسطس 2022؛ وتحتفظ الدار بالاسم والخطوط، وأوقفت Tabaquero.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"أوّل علامة لروكي باتيل، في التسعينيات، قبل أن تتّخذ الدار اسمه.","vitolas":[],"wrapper":"غير معلن"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"أُطلق في 2013 على يد Nish Patel، شقيق Rocky Patel ونائب الرئيس التنفيذي في الشركة، في أعقاب إصداره الأول عام 2011؛ وفي مارس 2024 يذكر مقال لـ Premium Cigar Association أنه يتولى قيادة الخط، الذي يُنتَج في نيكاراغوا. تبغ من San Andrés ومن مزارع الشركة في نيكاراغوا تحت الغلاف الخارجي، بمقاسات Robusto (5½ x 50) وToro (6 x 52) وTorpedo (6⅛ x 52) وSixty (6 x 60)، بحسب rockypatel.com.","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]',
  `source` = IF(LOCATE(CAST(' ; lot 5 : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 : ', ' ; '), `source`),
  `source` = IF(LOCATE(CAST(' ; requalification : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; requalification : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Rocky Patel';

-- ── Rojas Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST(' — et c''est ainsi que l''atlas le rencontre partout sans l''avoir jamais nommé : c''est lui qui a fait' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, ' — et c''est ainsi que l''atlas le rencontre partout sans l''avoir jamais nommé : c''est lui qui a fait', ' : c''est lui qui a fait'), `history`),
  `history_en` = IF(LOCATE(CAST(' — and that is how this atlas meets him everywhere without ever having named him: he made' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, ' — and that is how this atlas meets him everywhere without ever having named him: he made', ': he made'), `history_en`),
  `history_es` = IF(LOCATE(CAST(' — y así es como este atlas lo encuentra por todas partes sin haberlo nombrado nunca: es él quien hizo' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ' — y así es como este atlas lo encuentra por todas partes sin haberlo nombrado nunca: es él quien hizo', ': es él quien hizo'), `history_es`),
  `history_de` = IF(LOCATE(CAST(' — und so begegnet ihm dieser Atlas überall, ohne ihn je genannt zu haben: Er machte' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, ' — und so begegnet ihm dieser Atlas überall, ohne ihn je genannt zu haben: Er machte', ': Er machte'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('——本图集正是这样处处遇见他却从未点过他的名：Emilio' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '——本图集正是这样处处遇见他却从未点过他的名：Emilio', '：Emilio'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST(' — وهكذا يلتقيه هذا الأطلس في كلّ مكان دون أن يكون قد سمّاه قطّ: فهو من صنع' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, ' — وهكذا يلتقيه هذا الأطلس في كلّ مكان دون أن يكون قد سمّاه قطّ: فهو من صنع', ': فهو من صنع'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Rojas Cigars';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Trois maisons de cet atlas, et une quatrième à venir, sortent de ses mains.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Trois maisons de cet atlas, et une quatrième à venir, sortent de ses mains.', 'Les quatre maisons ont leur fiche.'), `history`),
  `history_en` = IF(LOCATE(CAST('Three houses in this atlas, and a fourth to come, come out of his hands.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Three houses in this atlas, and a fourth to come, come out of his hands.', 'The four houses have their entries.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Tres casas de este atlas, y una cuarta por venir, salen de sus manos.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Tres casas de este atlas, y una cuarta por venir, salen de sus manos.', 'Las cuatro casas tienen su ficha.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Drei Häuser dieses Atlas, und ein viertes, das noch kommt, gehen durch seine Hände.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Drei Häuser dieses Atlas, und ein viertes, das noch kommt, gehen durch seine Hände.', 'Die vier Häuser haben ihren Eintrag.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集里的三家、外加即将收录的第四家，都经他之手。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集里的三家、外加即将收录的第四家，都经他之手。', '这四家公司各有词条。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ثلاث دور في هذا الأطلس، ورابعة قادمة، تخرج من يديه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ثلاث دور في هذا الأطلس، ورابعة قادمة، تخرج من يديه.', 'للدور الأربع بطاقاتها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Rojas Cigars';

-- ── Selected Tobacco ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''atlas portait déjà les trois marques — Atabey, Byron et Bandolero — sans nommer la maison qui les tient ni l''homme qui les assemble. La maison a depuis ajouté une ligne à son propre nom, Alfonso.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''atlas portait déjà les trois marques — Atabey, Byron et Bandolero — sans nommer la maison qui les tient ni l''homme qui les assemble. La maison a depuis ajouté une ligne à son propre nom, Alfonso.', 'Les trois marques — Atabey, Byron et Bandolero — ont leur fiche. La maison a aussi une ligne à son propre nom, Alfonso.'), `history`),
  `history_en` = IF(LOCATE(CAST('This atlas already held all three brands — Atabey, Byron and Bandolero — without naming the house that owns them or the man who blends them. The house has since added a line under his own name, Alfonso.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'This atlas already held all three brands — Atabey, Byron and Bandolero — without naming the house that owns them or the man who blends them. The house has since added a line under his own name, Alfonso.', 'The three brands — Atabey, Byron and Bandolero — have their entries. The house also has a line under his own name, Alfonso.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Este atlas ya recogía las tres marcas —Atabey, Byron y Bandolero— sin nombrar la casa que las posee ni al hombre que las liga. La casa ha añadido después una línea con su propio nombre, Alfonso.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Este atlas ya recogía las tres marcas —Atabey, Byron y Bandolero— sin nombrar la casa que las posee ni al hombre que las liga. La casa ha añadido después una línea con su propio nombre, Alfonso.', 'Las tres marcas —Atabey, Byron y Bandolero— tienen su ficha. La casa tiene también una línea con su propio nombre, Alfonso.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Dieser Atlas führte alle drei Marken — Atabey, Byron und Bandolero — bereits, ohne das Haus zu nennen, dem sie gehören, oder den Mann, der sie mischt. Inzwischen kam eine Linie unter seinem eigenen Namen hinzu, Alfonso.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Dieser Atlas führte alle drei Marken — Atabey, Byron und Bandolero — bereits, ohne das Haus zu nennen, dem sie gehören, oder den Mann, der sie mischt. Inzwischen kam eine Linie unter seinem eigenen Namen hinzu, Alfonso.', 'Die drei Marken — Atabey, Byron und Bandolero — haben ihren Eintrag. Das Haus hat auch eine Linie unter seinem eigenen Namen, Alfonso.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集此前已收录这三个品牌，却未提及拥有它们的公司，也未提及为它们调配配方的人。此后该公司又推出了以其本人名字命名的 Alfonso 系列。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集此前已收录这三个品牌，却未提及拥有它们的公司，也未提及为它们调配配方的人。此后该公司又推出了以其本人名字命名的 Alfonso 系列。', '这三个品牌——Atabey、Byron 与 Bandolero——各有词条。该公司另有以其本人名字命名的 Alfonso 系列。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وكان هذا الأطلس يضمّ العلامات الثلاث — أتابي وبايرون وبانْدوليرو — دون أن يسمّي الدار التي تملكها ولا الرجل الذي يخلطها. وقد أضافت الدار لاحقًا خطًّا باسمه، ألفونسو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وكان هذا الأطلس يضمّ العلامات الثلاث — أتابي وبايرون وبانْدوليرو — دون أن يسمّي الدار التي تملكها ولا الرجل الذي يخلطها. وقد أضافت الدار لاحقًا خطًّا باسمه، ألفونسو.', 'والعلامات الثلاث — Atabey وByron وBandolero — لها بطاقاتها. وللدار أيضًا خطّ باسمه، Alfonso.'), `history_ar`),
