  `gamme_de` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","story":"Die ursprüngliche Serie, die die Marke seit 2003 trägt. Kubanische Grammatik, nicaraguanische Substanz: Pfeffer, Leder und ein langsamer, gleichmäßiger Abbrand, der allein der Rollkunst der Garcías zu verdanken ist.","vitolas":["Robusto","Corona"],"wrapper":"Habano aus Ecuador"},{"name":"Havana VI","color":"#B87333","force":"Medium","story":"Das sanftere Register des Hauses, eher für den Tag als für den Abend gedacht. Weniger Pfeffer, mehr Holz und Röstbrot.","vitolas":["Corona Gorda"],"wrapper":"Corojo"},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","story":"Pete Johnsons milde Seite — ecuadorianisches Connecticut über nicaraguanischen Tabaken, nach einer Stadt in Kuba benannt.","vitolas":[],"wrapper":"Ecuadorianisches Connecticut"},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","story":"2007 — zuerst in Gläsern verkauft, Pete Johnsons Linie nach kubanischer Art.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","story":"2008 — Broadleaf-Deckblatt über nicaraguanischen Tabaken.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Monster Series","color":"#4A3728","force":"Full","story":"Die jährliche Halloween-Edition seit 2008 — Frank, Drac, Face, Wolfman —, in gezählten Sargkisten.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","story":"2010 — beide Welten, eine preiswerte Zigarre.","vitolas":[],"wrapper":"Nicht angegeben"}]',
  `gamme_zh` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","story":"最初的系列，自2003年起就代表着这个品牌。古巴的语法，尼加拉瓜的原料：胡椒、皮革，以及缓慢均匀的燃烧——这全要归功于加西亚家族的卷制。","vitolas":["Robusto","Corona"],"wrapper":"厄瓜多尔哈瓦那种"},{"name":"Havana VI","color":"#B87333","force":"Medium","story":"这家更柔和的一面，为白天而非夜晚而设。胡椒更少，木质与烤面包更多。","vitolas":["Corona Gorda"],"wrapper":"Corojo"},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","story":"皮特·约翰逊的柔和一面——厄瓜多尔康涅狄格茄衣配尼加拉瓜烟叶，以古巴一座城镇命名。","vitolas":[],"wrapper":"厄瓜多尔康涅狄格"},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","story":"2007年——起初装在罐里卖，皮特·约翰逊的古巴风格系列。","vitolas":[],"wrapper":"未公开"},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","story":"2008年——broadleaf 茄衣配尼加拉瓜烟叶。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Monster Series","color":"#4A3728","force":"Full","story":"自2008年起的年度万圣节版——Frank、Drac、Face、Wolfman——限量棺材盒装。","vitolas":[],"wrapper":"未公开"},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","story":"2010年——两个世界，一支价格克制的雪茄。","vitolas":[],"wrapper":"未公开"}]',
  `gamme_ar` = '[{"name":"Brown Label","color":"#6B4423","force":"Full","story":"السلسلة الأصلية التي تحمل العلامة منذ 2003. قواعد كوبية ومادة نيكاراغوية: فلفل وجلد، واحتراق بطيء منتظم يدين بكل شيء للفّ آل غارسيا.","vitolas":["Robusto","Corona"],"wrapper":"هابانو إكوادوري"},{"name":"Havana VI","color":"#B87333","force":"Medium","story":"الوجه الألطف للدار، مصمَّم للنهار لا للمساء. فلفل أقل، وخشب وخبز محمّص أكثر.","vitolas":["Corona Gorda"],"wrapper":"Corojo"},{"name":"Cabaiguan","color":"#C9A96E","force":"Mild-Medium","story":"الجانب اللطيف عند بيت جونسون — كونيتيكت إكوادوري على أتبغة نيكاراغوية، باسم بلدة في كوبا.","vitolas":[],"wrapper":"كونيتيكت إكوادوري"},{"name":"Black Label","color":"#1F1F1F","force":"Medium-Full","story":"2007 — بِيعت أوّلًا في جرار، خطّ بيت جونسون على الطريقة الكوبية.","vitolas":[],"wrapper":"غير معلن"},{"name":"La Riqueza","color":"#3A2A1E","force":"Full","story":"2008 — غلاف برودليف على أتبغة نيكاراغوية.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Monster Series","color":"#4A3728","force":"Full","story":"الإصدار السنوي للهالوين منذ 2008 — Frank وDrac وFace وWolfman — في علب على شكل توابيت معدودة.","vitolas":[],"wrapper":"غير معلن"},{"name":"Ambos Mundos","color":"#8B5A2B","force":"Medium","story":"2010 — العالمان، سيجار معتدل الثمن.","vitolas":[],"wrapper":"غير معلن"}]',
  `source` = IF(LOCATE(CAST(' ; lot 5 : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 : ', ' ; '), `source`),
  `source` = IF(LOCATE(CAST(' ; lot 5 bis : ' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, ' ; lot 5 bis : ', ' ; '), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Tatuaje';

