  `history_es` = IF(LOCATE(CAST(', y faltaba en este atlas — una ausencia tanto más extraña cuanto que un fumador francés o español se la cruza' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, ', y faltaba en este atlas — una ausencia tanto más extraña cuanto que un fumador francés o español se la cruza', ': un fumador francés o español se la cruza'), `history_es`),
  `history_de` = IF(LOCATE(CAST(', und sie fehlte in diesem Atlas — eine umso seltsamere Abwesenheit, als ein französischer oder spanischer Raucher ihr in fast jedem Tabakladen begegnet' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, ', und sie fehlte in diesem Atlas — eine umso seltsamere Abwesenheit, als ein französischer oder spanischer Raucher ihr in fast jedem Tabakladen begegnet', ': Ein französischer oder spanischer Raucher begegnet ihr in fast jedem Tabakladen'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('，而它此前不在本图册中——这一缺席尤其奇怪，因为一位法国或西班牙烟客' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '，而它此前不在本图册中——这一缺席尤其奇怪，因为一位法国或西班牙烟客', '：一位法国或西班牙烟客'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('، وكانت غائبة عن هذا الأطلس — غياب أغرب ما فيه أن مدخّناً فرنسياً أو إسبانياً يصادفها' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '، وكانت غائبة عن هذا الأطلس — غياب أغرب ما فيه أن مدخّناً فرنسياً أو إسبانياً يصادفها', ': مدخّن فرنسي أو إسباني يصادفها'), `history_ar`),
  `updated_at` = NOW()
