-- ── Villiger Söhne ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('dont l''atlas porte désormais deux maisons, BIN et Golden Djawa' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'dont l''atlas porte désormais deux maisons, BIN et Golden Djawa', 'où roulent aussi deux maisons qui ont leur fiche, BIN et Golden Djawa'), `history`),
  `history_en` = IF(LOCATE(CAST('of which this atlas now carries two houses' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'of which this atlas now carries two houses', 'where two houses with their own entries also roll'), `history_en`),
  `history_es` = IF(LOCATE(CAST('de la que este atlas recoge ahora dos casas' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'de la que este atlas recoge ahora dos casas', 'donde también lían dos casas con ficha propia'), `history_es`),
  `history_de` = IF(LOCATE(CAST('von der dieser Atlas nun zwei Häuser führt' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'von der dieser Atlas nun zwei Häuser führt', 'wo auch zwei Häuser mit eigenem Eintrag rollen'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('本图集如今载有该城两家公司：BIN 和 Golden Djawa。任抹为瑞士卷制已久，只是无人用英语写下。

这份名单缺了一家工厂，印尼媒体点了它的名：Villiger 在东爪哇任抹有一座工厂——PT Villiger Tobacco Indonesia，在阿戎——就在 Besuki Na-Oogst 烟叶之城，本图集如今载有该城两家公司' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '本图集如今载有该城两家公司：BIN 和 Golden Djawa。任抹为瑞士卷制已久，只是无人用英语写下。

这份名单缺了一家工厂，印尼媒体点了它的名：Villiger 在东爪哇任抹有一座工厂——PT Villiger Tobacco Indonesia，在阿戎——就在 Besuki Na-Oogst 烟叶之城，本图集如今载有该城两家公司', '当地也有两家设有条目的公司在卷制：BIN 和 Golden Djawa。任抹为瑞士卷制已久，只是无人用英语写下。

这份名单缺了一家工厂，印尼媒体点了它的名：Villiger 在东爪哇任抹有一座工厂——PT Villiger Tobacco Indonesia，在阿戎——就在 Besuki Na-Oogst 烟叶之城，当地也有两家设有条目的公司在卷制'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('التي يحمل هذا الأطلس الآن دارين منها، BIN وGolden Djawa. تلفّ جمبر لسويسرا منذ زمن طويل من دون أن يكتب ذلك أحد بالإنجليزية.

ينقص هذه القائمة مصنعٌ تسمّيه الصحافة الإندونيسية: لـVilliger معملٌ في جمبر بجاوة الشرقية — PT Villiger Tobacco Indonesia في أجونغ — في مدينة تبغ Besuki Na-Oogst التي يحمل هذا الأطلس الآن دارين منها' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'التي يحمل هذا الأطلس الآن دارين منها، BIN وGolden Djawa. تلفّ جمبر لسويسرا منذ زمن طويل من دون أن يكتب ذلك أحد بالإنجليزية.

ينقص هذه القائمة مصنعٌ تسمّيه الصحافة الإندونيسية: لـVilliger معملٌ في جمبر بجاوة الشرقية — PT Villiger Tobacco Indonesia في أجونغ — في مدينة تبغ Besuki Na-Oogst التي يحمل هذا الأطلس الآن دارين منها', 'حيث تلفّ أيضًا داران لهما صفحة خاصة، BIN وGolden Djawa. تلفّ جمبر لسويسرا منذ زمن طويل من دون أن يكتب ذلك أحد بالإنجليزية.

ينقص هذه القائمة مصنعٌ تسمّيه الصحافة الإندونيسية: لـVilliger معملٌ في جمبر بجاوة الشرقية — PT Villiger Tobacco Indonesia في أجونغ — في مدينة تبغ Besuki Na-Oogst حيث تلفّ أيضًا داران لهما صفحة خاصة'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger Söhne';

