  `notes` = IF(LOCATE(CAST('Le cinquième recensement (septembre 2026) a relu Bahia dans la presse en portugais : le Recôncavo compte une dizaine de fabriques' AS BINARY), CAST(`notes` AS BINARY)) > 0, REPLACE(`notes`, 'Le cinquième recensement (septembre 2026) a relu Bahia dans la presse en portugais : le Recôncavo compte une dizaine de fabriques', 'Le Recôncavo compte une dizaine de fabriques, dit la presse en portugais'), `notes`),
