  `notes_es` = IF(LOCATE(CAST('El quinto censo (septiembre de 2026) releyó Bahía en la prensa en portugués: el Recôncavo cuenta una decena de fábricas' AS BINARY), CAST(`notes_es` AS BINARY)) > 0, REPLACE(`notes_es`, 'El quinto censo (septiembre de 2026) releyó Bahía en la prensa en portugués: el Recôncavo cuenta una decena de fábricas', 'El Recôncavo cuenta una decena de fábricas, dice la prensa en portugués'), `notes_es`),
