  `genese_es` = IF(LOCATE(CAST('; el atlas la escribía antes como un cruce del Criollo 98 con el Corojo de Diego Rodríguez, y ninguna fuente consultada lo sostiene' AS BINARY), CAST(`genese_es` AS BINARY)) > 0, REPLACE(`genese_es`, '; el atlas la escribía antes como un cruce del Criollo 98 con el Corojo de Diego Rodríguez, y ninguna fuente consultada lo sostiene', ''), `genese_es`),
  `genese_de` = IF(LOCATE(CAST('; dieser Atlas schrieb sie zuvor als Kreuzung des Criollo 98 mit dem Corojo von Diego Rodríguez, und keine befragte Quelle stützt das' AS BINARY), CAST(`genese_de` AS BINARY)) > 0, REPLACE(`genese_de`, '; dieser Atlas schrieb sie zuvor als Kreuzung des Criollo 98 mit dem Corojo von Diego Rodríguez, und keine befragte Quelle stützt das', ''), `genese_de`),
  `genese_zh` = IF(LOCATE(CAST('；本图集此前写它是 Criollo 98 与迭戈·罗德里格斯的 Corojo 的杂交，查阅的来源无一支持' AS BINARY), CAST(`genese_zh` AS BINARY)) > 0, REPLACE(`genese_zh`, '；本图集此前写它是 Criollo 98 与迭戈·罗德里格斯的 Corojo 的杂交，查阅的来源无一支持', ''), `genese_zh`),
  `genese_ar` = IF(LOCATE(CAST('؛ وكان هذا الأطلس يكتبها من قبل تهجينًا للكريولو 98 مع كوروخو دييغو رودريغيس، ولا يدعم ذلك أيّ مصدر راجعناه' AS BINARY), CAST(`genese_ar` AS BINARY)) > 0, REPLACE(`genese_ar`, '؛ وكان هذا الأطلس يكتبها من قبل تهجينًا للكريولو 98 مع كوروخو دييغو رودريغيس، ولا يدعم ذلك أيّ مصدر راجعناه', ''), `genese_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'nicaragua-corojo-99';

-- ── feuilles jamaique-cow-tongue : culture ──
UPDATE `feuilles` SET
  `culture` = IF(LOCATE(CAST(', là où l''atlas écrivait une plaine calcaire ; la fiche garde les deux' AS BINARY), CAST(`culture` AS BINARY)) > 0, REPLACE(`culture`, ', là où l''atlas écrivait une plaine calcaire ; la fiche garde les deux', ''), `culture`),
  `culture_en` = IF(LOCATE(CAST(', where this atlas wrote a limestone plain; the entry keeps both' AS BINARY), CAST(`culture_en` AS BINARY)) > 0, REPLACE(`culture_en`, ', where this atlas wrote a limestone plain; the entry keeps both', ''), `culture_en`),
  `culture_es` = IF(LOCATE(CAST(', donde el atlas escribía una llanura calcárea; la ficha conserva los dos' AS BINARY), CAST(`culture_es` AS BINARY)) > 0, REPLACE(`culture_es`, ', donde el atlas escribía una llanura calcárea; la ficha conserva los dos', ''), `culture_es`),
  `culture_de` = IF(LOCATE(CAST(', wo dieser Atlas eine Kalkebene schrieb; der Eintrag behält beides' AS BINARY), CAST(`culture_de` AS BINARY)) > 0, REPLACE(`culture_de`, ', wo dieser Atlas eine Kalkebene schrieb; der Eintrag behält beides', ''), `culture_de`),
  `culture_zh` = IF(LOCATE(CAST('，本图集原先写的是石灰岩平原；词条两者都保留' AS BINARY), CAST(`culture_zh` AS BINARY)) > 0, REPLACE(`culture_zh`, '，本图集原先写的是石灰岩平原；词条两者都保留', ''), `culture_zh`),
  `culture_ar` = IF(LOCATE(CAST('، حيث كان هذا الأطلس يكتب سهلًا كلسيًّا؛ تحتفظ البطاقة بالاثنين' AS BINARY), CAST(`culture_ar` AS BINARY)) > 0, REPLACE(`culture_ar`, '، حيث كان هذا الأطلس يكتب سهلًا كلسيًّا؛ تحتفظ البطاقة بالاثنين', ''), `culture_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'jamaique-cow-tongue';

UPDATE `feuilles` SET
  `culture` = IF(LOCATE(CAST('; l''atlas n''a rien trouvé de plus récent sur ces champs, et le dit' AS BINARY), CAST(`culture` AS BINARY)) > 0, REPLACE(`culture`, '; l''atlas n''a rien trouvé de plus récent sur ces champs, et le dit', '; rien de plus récent n''est connu sur ces champs'), `culture`),
  `culture_en` = IF(LOCATE(CAST('; the atlas has found nothing more recent on those fields, and says so' AS BINARY), CAST(`culture_en` AS BINARY)) > 0, REPLACE(`culture_en`, '; the atlas has found nothing more recent on those fields, and says so', '; nothing more recent is known about those fields'), `culture_en`),
  `culture_es` = IF(LOCATE(CAST('; el atlas no ha encontrado nada más reciente sobre esos campos, y lo dice' AS BINARY), CAST(`culture_es` AS BINARY)) > 0, REPLACE(`culture_es`, '; el atlas no ha encontrado nada más reciente sobre esos campos, y lo dice', '; no se conoce nada más reciente sobre esos campos'), `culture_es`),
  `culture_de` = IF(LOCATE(CAST('; der Atlas hat nichts Neueres über diese Felder gefunden, und sagt es' AS BINARY), CAST(`culture_de` AS BINARY)) > 0, REPLACE(`culture_de`, '; der Atlas hat nichts Neueres über diese Felder gefunden, und sagt es', '; über diese Felder ist nichts Neueres bekannt'), `culture_de`),
  `culture_zh` = IF(LOCATE(CAST('；图集没有找到关于这些田地更新的资料，并如实说明' AS BINARY), CAST(`culture_zh` AS BINARY)) > 0, REPLACE(`culture_zh`, '；图集没有找到关于这些田地更新的资料，并如实说明', '；关于这些田地，尚不知有更新的资料'), `culture_zh`),
  `culture_ar` = IF(LOCATE(CAST('؛ ولم يجد الأطلس شيئًا أحدث عن تلك الحقول، ويقول ذلك' AS BINARY), CAST(`culture_ar` AS BINARY)) > 0, REPLACE(`culture_ar`, '؛ ولم يجد الأطلس شيئًا أحدث عن تلك الحقول، ويقول ذلك', '؛ ولا يُعرف شيء أحدث عن تلك الحقول'), `culture_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'jamaique-cow-tongue';

-- ── feuilles jamaique-cow-tongue : caracteres ──
UPDATE `feuilles` SET
  `caracteres` = IF(LOCATE(CAST('Une feuille dont l''atlas parle surtout au passé, et c''est assumé.' AS BINARY), CAST(`caracteres` AS BINARY)) > 0, REPLACE(`caracteres`, 'Une feuille dont l''atlas parle surtout au passé, et c''est assumé.', 'Une feuille qui se raconte surtout au passé.'), `caracteres`),
  `caracteres_en` = IF(LOCATE(CAST('A leaf this atlas speaks of mostly in the past tense, and that is deliberate.' AS BINARY), CAST(`caracteres_en` AS BINARY)) > 0, REPLACE(`caracteres_en`, 'A leaf this atlas speaks of mostly in the past tense, and that is deliberate.', 'A leaf that is told mostly in the past tense.'), `caracteres_en`),
  `caracteres_es` = IF(LOCATE(CAST('Una hoja de la que el atlas habla sobre todo en pasado, y es deliberado.' AS BINARY), CAST(`caracteres_es` AS BINARY)) > 0, REPLACE(`caracteres_es`, 'Una hoja de la que el atlas habla sobre todo en pasado, y es deliberado.', 'Una hoja que se cuenta sobre todo en pasado.'), `caracteres_es`),
  `caracteres_de` = IF(LOCATE(CAST('dieser Atlas vor allem im Präteritum spricht, und das ist gewollt.' AS BINARY), CAST(`caracteres_de` AS BINARY)) > 0, REPLACE(`caracteres_de`, 'dieser Atlas vor allem im Präteritum spricht, und das ist gewollt.', 'vor allem im Präteritum erzählt wird.'), `caracteres_de`),
  `caracteres_zh` = IF(LOCATE(CAST('本图集谈到这片叶子时多用过去时，这是有意的。' AS BINARY), CAST(`caracteres_zh` AS BINARY)) > 0, REPLACE(`caracteres_zh`, '本图集谈到这片叶子时多用过去时，这是有意的。', '一片多用过去时讲述的叶子。'), `caracteres_zh`),
  `caracteres_ar` = IF(LOCATE(CAST('ورقة يتحدّث عنها هذا الأطلس بصيغة الماضي في الغالب، وذلك مقصود.' AS BINARY), CAST(`caracteres_ar` AS BINARY)) > 0, REPLACE(`caracteres_ar`, 'ورقة يتحدّث عنها هذا الأطلس بصيغة الماضي في الغالب، وذلك مقصود.', 'ورقة يُحكى عنها في الغالب بصيغة الماضي.'), `caracteres_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'jamaique-cow-tongue';

-- ── feuilles philippines-cagayan : caracteres ──
UPDATE `feuilles` SET
  `caracteres` = IF(LOCATE(CAST(' L''atlas écrivait deux autres souches, Cimaba et Viscaya : aucune source ne les nomme, et il les retire.' AS BINARY), CAST(`caracteres` AS BINARY)) > 0, REPLACE(`caracteres`, ' L''atlas écrivait deux autres souches, Cimaba et Viscaya : aucune source ne les nomme, et il les retire.', ''), `caracteres`),
  `caracteres_en` = IF(LOCATE(CAST(' This atlas wrote two other strains, Cimaba and Viscaya: no source names them, and it withdraws them.' AS BINARY), CAST(`caracteres_en` AS BINARY)) > 0, REPLACE(`caracteres_en`, ' This atlas wrote two other strains, Cimaba and Viscaya: no source names them, and it withdraws them.', ''), `caracteres_en`),
  `caracteres_es` = IF(LOCATE(CAST(' El atlas escribía otras dos cepas, Cimaba y Viscaya: ninguna fuente las nombra, y las retira.' AS BINARY), CAST(`caracteres_es` AS BINARY)) > 0, REPLACE(`caracteres_es`, ' El atlas escribía otras dos cepas, Cimaba y Viscaya: ninguna fuente las nombra, y las retira.', ''), `caracteres_es`),
  `caracteres_de` = IF(LOCATE(CAST(' Dieser Atlas schrieb zwei weitere Stämme, Cimaba und Viscaya: Keine Quelle nennt sie, und er zieht sie zurück.' AS BINARY), CAST(`caracteres_de` AS BINARY)) > 0, REPLACE(`caracteres_de`, ' Dieser Atlas schrieb zwei weitere Stämme, Cimaba und Viscaya: Keine Quelle nennt sie, und er zieht sie zurück.', ''), `caracteres_de`),
  `caracteres_zh` = IF(LOCATE(CAST('本图集原先还写了两个品系 Cimaba 和 Viscaya：没有来源提到它们，予以撤回。' AS BINARY), CAST(`caracteres_zh` AS BINARY)) > 0, REPLACE(`caracteres_zh`, '本图集原先还写了两个品系 Cimaba 和 Viscaya：没有来源提到它们，予以撤回。', ''), `caracteres_zh`),
  `caracteres_ar` = IF(LOCATE(CAST(' وكان هذا الأطلس يكتب سلالتين أخريين، Cimaba وViscaya: لا يسمّيهما مصدر، ويسحبهما.' AS BINARY), CAST(`caracteres_ar` AS BINARY)) > 0, REPLACE(`caracteres_ar`, ' وكان هذا الأطلس يكتب سلالتين أخريين، Cimaba وViscaya: لا يسمّيهما مصدر، ويسحبهما.', ''), `caracteres_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'philippines-cagayan';

-- ── feuilles nicaragua-habano : culture ──
UPDATE `feuilles` SET
  `culture` = IF(LOCATE(CAST('l''atlas le retrouve en Équateur et au Panama' AS BINARY), CAST(`culture` AS BINARY)) > 0, REPLACE(`culture`, 'l''atlas le retrouve en Équateur et au Panama', 'on le retrouve en Équateur et au Panama'), `culture`),
  `culture_en` = IF(LOCATE(CAST('the atlas meets it again' AS BINARY), CAST(`culture_en` AS BINARY)) > 0, REPLACE(`culture_en`, 'the atlas meets it again', 'one meets it again'), `culture_en`),
  `culture_es` = IF(LOCATE(CAST('el atlas la reencuentra' AS BINARY), CAST(`culture_es` AS BINARY)) > 0, REPLACE(`culture_es`, 'el atlas la reencuentra', 'se la reencuentra'), `culture_es`),
  `culture_de` = IF(LOCATE(CAST('der Atlas trifft es' AS BINARY), CAST(`culture_de` AS BINARY)) > 0, REPLACE(`culture_de`, 'der Atlas trifft es', 'man trifft es'), `culture_de`),
  `culture_zh` = IF(LOCATE(CAST('本图册在' AS BINARY), CAST(`culture_zh` AS BINARY)) > 0, REPLACE(`culture_zh`, '本图册在', '人们在'), `culture_zh`),
  `culture_ar` = IF(LOCATE(CAST('ويلتقيها الأطلس' AS BINARY), CAST(`culture_ar` AS BINARY)) > 0, REPLACE(`culture_ar`, 'ويلتقيها الأطلس', 'ويلتقيها المرء'), `culture_ar`),
  `updated_at` = NOW()
 WHERE `id` = 'nicaragua-habano';

-- ── feuilles indonesie-besuki : source ──
UPDATE `feuilles` SET
  `source` = 'ptmdr.co.id « Tobacco of Jember History » (George Birnie obtient en 1859 un droit d''emphytéose à Jenggawah, près de Jember, pour le Besuki Na Oogst ; la Landbouw Maatschappij Oud Djember ; les feuilles Na Oogst exportées vers Brême pour la cape) ; journal.unnes.ac.id, Wardhono, « The Quality Development of Besuki Na-Oogst Tobacco in Jember Regency » ; indonesia.travel (le musée du tabac de Jember) ; cigarinspector.com « Besuki » (Vroege Oogst et Na Oogst) ; tribunnews.com et umkm.kompas.com (le tabac de Jember chez Rizona et BIN Cigar) — sources en anglais et en indonésien',
  `updated_at` = NOW()
 WHERE `id` = 'indonesie-besuki';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'producer_countries', x.`id`, 'notes', l.lang, SHA1(x.`notes`), 'machine', NULL, NOW()
  FROM `producer_countries` x
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE x.`id` = 'brazil'
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

UPDATE `translation_status` SET `statut` = 'relu', `relecteur` = 'expert-traduction (agent)', `maj` = NOW() WHERE `entite` = 'producer_countries' AND `entite_id` = 'brazil' AND `champ` = 'notes' AND `lang` = 'en';

