        UNION ALL SELECT 'Patina Cigars' hote, 'history' champ
        UNION ALL SELECT 'Patoro' hote, 'history' champ
        UNION ALL SELECT 'Principle Cigars' hote, 'history' champ
        UNION ALL SELECT 'Punch' hote, 'history' champ
        UNION ALL SELECT 'Quintero' hote, 'history' champ
