SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme', 'celebrities', 'pairings') AND b.`name` IN ('262 Cigars','7-20-4','A.J. Fernandez','Aganorsa Leaf','Aging Room','Agrotabacos','Alec Bradley','All Saints Cigars','Aruhiba','Atabey','BIN Cigar','Baccarat','Black Label Trading Co.','Bolivar','Caldwell Cigar Co.','Casa Turrent','Chaba','Compagnia Toscana Sigari','Cornelius & Anthony','Crowned Heads','Cuban Crafters','Cuban Stock Cigar Co.','Curivari','De Los Reyes Cigars','Debonaire House','Don Diego','Dona Flor','Drew Estate','Dunbarton Tobacco & Trust','Espinosa','Fable Cigars','Fonseca Nicaraguayen','Foundation Cigar Company','Fratello','General Cigar','Golden Djawa','HVC Cigars','Hoyo de Monterrey','IGM Cigars','Illusione','J. Fuego','J.C. Newman','Jake Wyatt Cigar Co.','José L. Piedra','Kelner Boutique Factory','La Aurora','La Barba','La Flor de Cano','La Flor de Copán','Leite & Alves','Matacan','Maya Selva Cigars','Meerapfel','Menendez Amerino','Monte Pascoal','Mosi Oa Tunya','My Father','Nat Sherman','Nomad','Ozgener Family Cigars','Patina Cigars','Patoro','Principle Cigars','Punch','Quintero','Reyes Family Cigars','Rizona Baru','RoMa Craft Tobac','Rocky Patel','Rojas Cigars','Selected Tobacco','Sindicato Cigar Group','Southern Draw','Tabacalera','Tabacalera R. Paxtián','Tabacalera William Ventura','Tabaqueria de Filipinas','Tatuaje','Temple Hall','Trinidad','VegaFina','Vegas Robaina','Vegueros','Villiger','Villiger Söhne','Warped')) = 0 AS sceaux_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(x.`notes`) AND x.`id` = 'brazil') = 0 AS sceau_autre_1,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(x.`notes`) AND x.`id` = 'ecuador') = 0 AS sceau_autre_2,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(x.`notes`) AND x.`id` = 'mexico') = 0 AS sceau_autre_3,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(x.`notes`) AND x.`id` = 'philippines') = 0 AS sceau_autre_4,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'genese' AND t.`source_hash` <> SHA1(x.`genese`) AND x.`id` = 'dominicaine-san-vicente') = 0 AS sceau_autre_5,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'genese' AND t.`source_hash` <> SHA1(x.`genese`) AND x.`id` = 'indonesie-deli') = 0 AS sceau_autre_6,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'genese' AND t.`source_hash` <> SHA1(x.`genese`) AND x.`id` = 'nicaragua-corojo-99') = 0 AS sceau_autre_7,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'culture' AND t.`source_hash` <> SHA1(x.`culture`) AND x.`id` = 'jamaique-cow-tongue') = 0 AS sceau_autre_8,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'caracteres' AND t.`source_hash` <> SHA1(x.`caracteres`) AND x.`id` = 'jamaique-cow-tongue') = 0 AS sceau_autre_9,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'caracteres' AND t.`source_hash` <> SHA1(x.`caracteres`) AND x.`id` = 'philippines-cagayan') = 0 AS sceau_autre_10,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `feuilles` x ON x.`id` = t.`entite_id` AND t.`entite` = 'feuilles'
         WHERE t.`champ` = 'culture' AND t.`source_hash` <> SHA1(x.`culture`) AND x.`id` = 'nicaragua-habano') = 0 AS sceau_autre_11,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 262') AS journal_non_tronque;
